window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"sermons","number":182,"source":"خطبه 182.docx","mode":"explicit-parts","parts":["خطبه ۱۸۲\nبخش اول\nمتن:\nرُوِيَ عَنْ نَوْفٍ الْبَكَالِيِّ قَالَ خَطَبَنَا بِهَذِهِ الْخُطْبَةِ أَمِيرُ الْمُؤْمِنِينَ عَلِيٌّ (علیه السلام) بِالْكُوفَةِ وَ هُوَ قَائِمٌ عَلَى حِجَارَةٍ نَصَبَهَا لَهُ جَعْدَةُ بْنُ هُبَيْرَةَ الْمَخْزُومِيُّ وَ عَلَيْهِ مِدْرَعَةٌ مِنْ صُوفٍ وَ حَمَائِلُ سَيْفِهِ لِيفٌ وَ فِي رِجْلَيْهِ نَعْلَانِ مِنْ لِيفٍ وَ كَأَنَّ جَبِينَهُ ثَفِنَةُ بَعِيرٍ، فَقَالَ (علیه السلام):\nحمد اللّه و استعانته:\nالْحَمْدُ لِلَّهِ الَّذِي إِلَيْهِ مَصَائِرُ الْخَلْقِ وَ عَوَاقِبُ الْأَمْرِ، نَحْمَدُهُ عَلَى عَظِيمِ إِحْسَانِهِ وَ نَيِّرِ بُرْهَانِهِ وَ نَوَامِي فَضْلِهِ وَ امْتِنَانِهِ؛ حَمْداً يَكُونُ لِحَقِّهِ قَضَاءً وَ لِشُكْرِهِ أَدَاءً وَ إِلَى ثَوَابِهِ مُقَرِّباً وَ لِحُسْنِ مَزِيدِهِ مُوجِباً؛ وَ نَسْتَعِينُ بِهِ اسْتِعَانَةَ رَاجٍ لِفَضْلِهِ، مُؤَمِّلٍ لِنَفْعِهِ، وَاثِقٍ بِدَفْعِهِ، مُعْتَرِفٍ لَهُ بِالطَّوْلِ، مُذْعِنٍ لَهُ بِالْعَمَلِ وَ الْقَوْلِ؛ وَ نُؤْمِنُ بِهِ إِيمَانَ مَنْ رَجَاهُ مُوقِناً وَ أَنَابَ إِلَيْهِ مُؤْمِناً وَ خَنَعَ لَهُ مُذْعِناً وَ أَخْلَصَ لَهُ مُوَحِّداً وَ عَظَّمَهُ مُمَجِّداً وَ لَاذَ بِهِ رَاغِباً مُجْتَهِداً.\nترجمه:\nحمد و سپاس مخصوص خداوندى است که سرانجام مخلوقات و عواقب امور به او منتهى مى گردد. او را بر احسان عظيم و برهان روشن و فضل و نعمت فزاينده اش سپاس مى گوييم; سپاسى که آنچه را شايسته حق اوست ادا کند و آنچه در خور شکر اوست انجام دهد و ما را به ثوابش نزديک سازد و موجب فزونى نعمتش گردد. و از او استعانت مى جوييم استعانت کسى که به فضل پروردگار اميدوار است و به سودش آرزومند و به دفع زيان ها مطمئن و به نعمتش معترف و کردار و رفتار به او اذعان دارد. به او ايمان داريم، ايمان کسى که با يقين کامل به او اميدوار است و با اعتقاد خالص به او توجه دارد، ايمان کسى که در برابر او خاضع و با خلوص نيّت به توحيد او عقيده مند است. با تمجيد فراوان به بزرگداشت او مى پردازد و با رغبت و کوشش به او پناهنده مى شود.\nتفسیر:\nاهمیت خطبه به دو جهت است:\n۱. محتوا با موضوعات مهم و متعدد.\n۲. از آخرین خطبه‌های حضرت است؛ این خطبه کمتر از یک هفته قبل از شهادت حضرت ایراد شد.\nرُوِیَ عَنْ نَوْفٍ الْبِکَالِیِّ قَالَ:\nنوف بکالی در این چند جمله به‌صورت کامل موقعیت حضرت را در حین خطبه توضیح داده است.\nخَطَبَنَا بِهَذِهِ الْخُطْبَةِ أَمِیرُ الْمُؤْمِنِینَ عَلِیٌّ (عَلَیْهِ السَّلَامُ) بِالْکُوفَةِ وَهُوَ قَائِمٌ عَلَی حِجَارَةٍ نَصَبَهَا لَهُ جَعْدَةُ بْنُ هُبَیْرَةَ الْمَخْزُومِیُّ:\nاین خطبه را امیرالمؤمنین در حالی ایراد کردند که بر روی تکه سنگی که جعده بن هبیره المخزومی برای ایشان به حالت منبر درآورده بود ایستاده بودند.\nوَعَلَیْهِ مِدْرَعَةٌ مِنْ صُوفٍ:\nدرحالی‌که لباسی از پشم (صوف) بر تن داشتند؛ لباس خشن که فقیرترین مردم بر تن داشتند.\nوجه تسمیه صوفیه طبق یکی از اقوال همین است که تصوف نیز برای سرلوحه قراردادن زهد حضرت این‌گونه لباس می‌پوشیدند. البته که صوفیه امروز خلاف حضرت عمل نمودند و فقط به پوشیدن لباس پشمین اکتفا کردند؛ چرا که حضرت در کنار زهدی که در پوشش داشتند در عمل هیچ‌گاه شمشیر از کمرشان جدا نشد (همان‌گونه که در جمله بعدی آمده است). این چیزی که صوفیه امروز در پیش گرفته (سکوت و انفعال و حتی همدستی با استکبار) خلاف منش حضرت است. امیرالمؤمنین را باید از جمیع جهات بشناسیم و از جمیع جهات از ایشان تبعیت کنیم.\nوَحَمَائِلُ سَیْفِهِ لِیفٌ:\nکمربندی (حمائل) که شمشیر را به آن می‌بندند و آن از لیف خرما بود (مثل پادشاهان طلاکوب و چرمی نبود).\nوَفِی رِجْلَیْهِ نَعْلَانِ مِنْ لِیفٍ:\nو در پایشان نعلینی از لیف خرما بود (باوجود حاکمیت حضرت، لباس و کمربند در سطح پایین‌ترین مردم بود).\nوَکَأَنَّ جَبِینَهُ ثَفِنَةُ بَعِیرٍ فَقَالَ (عَلَیْهِ السَّلَامُ):\nزانوهای شتر ازآن‌جهت که مدام روی خاک زانو می‌زند پر از پینه است. پیشانی حضرت به سبب سجده‌های فراوان پر از پینه بود (ثفنة).\nالْحَمْدُ لِلَّهِ الَّذِی إِلَیْهِ مَصَائِرُ الْخَلْقِ وَعَوَاقِبُ الْأَمْرِ:\nحمد مختص به خداست که بازگشت همه مخلوقات و عاقبت همه امور به‌سوی اوست.\nدیگران حمد و ستایش ندارند، همه حمد و ستایش از آنِ خداست. اگر گاهی از دیگران تشکر و قدردانی می‌نماییم می‌خواهیم بگوییم تو نماینده خدایی و خدا به برکت و به واسطه تو مشکل ما را حل کرد، وگرنه همه حمد به‌تمام‌معنا از آنِ خداست.\nعواقب الامر (انا لله و انا الیه راجعون).\nخدا هم اول است و هم آخر؛ از خدا شروع شده، خدا خلق کرده و باز همکار تمام نمی‌شود و همه باز برمی‌گردند به وجود خداوند متعال. در اینجا هم بازگشت به‌سوی خدا و هم جریان معاد مطرح است.\nمعاد چیست؟ مالک یوم‌الدین خداست؛ پس بازگشت به‌سوی خداوند است.\nنَحْمَدُهُ عَلَی عَظِیمِ إِحْسَانِهِ:\nخدا را به سبب احسان عظیمش شکر می‌کنیم.\nوَنَیِّرِ بُرْهَانِهِ:\nخدا را به‌خاطر برهان‌های آشکار (نیِّر) شکر می‌کنیم.\nشکر خدا به‌خاطر اینکه خود را با بهترین برهان‌ها به ما شناساند؛ خود خدا و مخلوقات او گواه بر وجود اوست.\nوَنَوَامِی فَضْلِهِ وَامْتِنَانِهِ:\nبه‌خاطر همه فضل و نعمت‌های نامیِ خدا شکر می‌کنیم.\nخدا فضل و امتنان را با وصف نوامی آورده به معنی فزاینده و رشدکننده مداوم؛ برخلاف فضل دیگران که رشدی ندارد، عقیم است و برکتی ندارد.\nحَمْداً یَکُونُ لِحَقِّهِ قَضَاءً:\nحمد می‌کنیم خدا را، حمدی که حق خدا را جبران و ادا کند (قضاءً).\nالحمدلله کما هو اهله: خدا را آن‌گونه که اهلش است شکر می‌کنیم.\nوَلِشُکْرِهِ أَدَاءً:\nحمد می‌کنیم خدا را آن‌گونه که اداکننده شکرش باشد.\nوَإِلَی ثَوَابِهِ مُقَرِّباً:\nیک حمدی که مقرب کننده ما به خدا باشد.\nوَلِحُسْنِ مَزِیدِهِ مُوجِباً:\nحمدی که باعث افزایش نعمت‌ها شود.\nدر واقع کلام حضرت این است که حمدی کنید که این ویژگی‌ها را داشته باشد.\nویژگی‌های حمد حقیقی از منظر حضرت:\n۱. لِحَقِّهِ قَضَاءً باشد.\n۲. لِشُکْرِهِ أَدَاءً باشد.\n۳. إِلَی ثَوَابِهِ مُقَرِّباً باشد.\n۴. لِحُسْنِ مَزِیدِهِ مُوجِباً باشد.\nحتی انبیا و اولیا هم نتوانستند از پسِ حمد الهی بربیایند، چرا که همه وجود ما از آنِ خداست؛ پس چگونه حق این‌همه نعمت را ادا کنیم، چون هرچه شکر کنیم بیشتر بدهکار می‌شویم. ولی هدف همین است که به این نکته برسیم که ما هرچه شکر کنیم نمی‌توانیم حق شکر را ادا کنیم و پی‌بردن به این (نتوانستن) در منظر خدا یعنی حمد واقعی.\nروایتی از وجود امام صادق (علیه‌السلام) در ثواب الاعمال ج ۱ ص ۲۸ آمده است:\nقَالَ (عَلَیْهِ السَّلَامُ): «الْحَمْدُ لِلَّهِ کَمَا هُوَ أَهْلُهُ، شُغِلَ کُتَّابُ السَّمَاءِ»، قُلْتُ: وَکَیْفَ یُشْغَلُ کُتَّابُ السَّمَاءِ؟ قَالَ: «اللَّهُمَّ إِنَّا لَا نَعْلَمُ الْغَیْبَ»، فَقَالَ: «اکْتُبُوهَا کَمَا قَالَهَا عَبْدِی وَعَلَیَّ ثَوَابُهَا». أَقُولُ: وَتَقَدَّمَ مَا یَدُلُّ عَلَی ذَلِکَ.\nملائکه در نوشتن ثواب کسی که خدا را با جمله «الحمدلله کما هو اهله» حمد می‌کند عاجزند، زیرا آن‌ها هم حقیقت شکر و حمد خدا را نمی‌دانند؛ پس بر خداوند عرضه می‌دارند و خداوند می‌فرماید: همان‌گونه که بنده من گفت بنویسید که ثواب آن بر عهده من است.\nوَنَسْتَعِینُ بِهِ اسْتِعَانَةَ رَاجٍ لِفَضْلِهِ:\nمانند کسانی که به فضل تو امید (راجٍ) قطعی دارند از تو طلب کمک می‌نماییم (چنان‌که موقع نماز باران چتر با خود می‌برند).\nمُؤَمِّلٍ لِنَفْعِهِ:\nمثل کسانی که آرزو دارند که تو به آن‌ها نفع برسانی (دعایی که پشت آن آرزومندی است و خشک‌وخالی نیست).\nوَاثِقٍ بِدَفْعِهِ:\nمانند دعای کسانی که اطمینان دارند (واثق) که تو به برکت این دعا بلاها را از آن‌ها دور می‌کنی.\nمُعْتَرِفٍ لَهُ بِالطَّوْلِ:\nمثل کسی که به نعمت‌ها (طول) اعتراف می‌کند (خدایا تو از نعمت کم نگذاشته‌ای، این من بودم که به خودم ظلم کرده‌ام).\nمُذْعِنٍ لَهُ بِالْعَمَلِ وَالْقَوْلِ:\nمانند کسی که با عمل و قول اذعان داشته باشد از تو طلب کمک می‌کنم.\nاستعانت نیز مثل حمد است و باید ویژگی‌هایی داشته باشد.\nویژگی‌های استعانت حقیقی از منظر امام:\n۱. رَاجٍ لِفَضْلِهِ باشد.\n۲. مُؤَمِّلٍ لِنَفْعِهِ باشد.\n۳. وَاثِقٍ بِدَفْعِهِ باشد.\n۴. مُعْتَرِفٍ لَهُ بِالطَّوْلِ باشد.\n۵. مُذْعِنٍ لَهُ بِالْعَمَلِ وَالْقَوْلِ باشد.\nاگر چنین کمک خواستنی حاصل شود، حتماً کمک می‌شود.\nبرخی از ما در قول فقط خداخدا می‌کنیم و در عمل چنین نیستیم.\nحضرت در بخشی از خطبه ۱۵۹ فرمود:\n«یَرْجُو اللَّهَ فِی الْکَبِیرِ وَیَرْجُو الْعِبَادَ فِی الصَّغِیرِ»\nبرخی در امور بزرگ از خدا طلب کمک می‌کنند و در امور کوچک به بندگان امید دارند که این خود یک نوع شرک به‌حساب می‌آید. همه چیز را باید از خدا خواست، چه کوچک، چه بزرگ باشد.\nدر خطبه ۹۱ آمده:\n«وَلَا أُوَجِّهُهُ إِلَی مَعَادِنِ الْخَیْبَةِ»\nخدایا من به مردم رو نمی‌کنم؛ چون آن‌ها معدن ناامیدی هستند. مردم نه‌تنها کمک نمی‌کنند؛ بلکه موجب ناامیدی هم می‌شوند.\nامید به غیر خدا نشان از نشناختن خداست.\nدر هر زمان که به درگاه خدا برویم و با هر زبانی، هرچه بخواهیم به شرطی که امید داشته باشیم، خداوند می‌دهد.\nوَنُؤْمِنُ بِهِ إِیمَانَ مَنْ رَجَاهُ مُوقِناً:\nما ایمان داریم به خدا، ولی ایمان کسی که با یقین به وجود خداوند امید دارد؛ یقین دارد که خدا می‌شنود و مستجاب می‌کند.\nدر روایت داریم دعایی که مستجاب نشود نداریم؛ یا همان را می‌دهند، یا نصفش را می‌دهند، یا ذخیره قبر و قیامت آن شخص می‌شود.\nوَأَنَابَ إِلَیْهِ مُؤْمِناً:\nما ایمان داریم به خدا، ایمان کسی که به بازگشت به‌سوی خدا ایمان دارد.\nبازگشتن به‌سوی خدا یعنی کسی که توجه به خدا دارد (اناب).\nوَخَنَعَ لَهُ مُذْعِناً:\nمانند کسی که خضوع (خَنَعَ) کرده در برابر تو درحالی‌که به جایگاهش اذعان دارد.\nشخص گردن‌کلفت سر خم نمی‌کند؛ وقتی اعتراف به کمبودها نداشته باشیم در مقابل خدا نمی‌شکنیم و تا در مقابل خدا نشکنیم بزرگ نمی‌شویم.\nوَأَخْلَصَ لَهُ مُوَحِّداً:\nخدایا ما به تو مانند کسی که به وحدانیت تو خلوص دارد ایمان آوردیم (بدون ذره‌ای شرک، ریا و خودنمایی).\nوَعَظَّمَهُ مُمَجِّداً:\nخدایا ما ایمان داریم به تو مانند ایمان کسی که با تمجید از تو یاد می‌کند و تو را بزرگ می‌دارد.\nخدایا اگر می‌خواهیم تو را به بزرگی یاد کنیم باید در خور تو تمجید کنیم.\nباید مواظب باشیم در تمجید خدا از عباراتی استفاده نکنیم که موجب نقص در وجود خدا گردد، بلکه همچون امام علی (علیه‌السلام) ایشان را بزرگوارانه تمجید کنیم.\nوَلَاذَ بِهِ رَاغِباً مُجْتَهِداً:\nما به تو ایمان داریم، ایمان کسی که به تو از روی رغبت و همراه با تلاش پناهنده شده است (لاذ).\nمانند کسی که نزد تو سنگر گرفته و شیطان در کمین او است.\nایمانی که ما در آن روی خودِ ایمان حساب باز نکرده‌ایم، بلکه به آغوش تو حساب باز کردیم.\nپناهی که نه از روی ترس جهنم باشد، بلکه از روی میل و رغبت و خواستن باشد، عاشقانه باشد. ایمان داشتن به تنبلی نیست؛ بلکه به جهد و تلاش است.\nویژگی‌های ایمان حقیقی از منظر حضرت:\n۱. رَجَاهُ مُوقِناً باشد.\n۲. أَنَابَ إِلَیْهِ مُؤْمِناً باشد.\n۳. خَنَعَ لَهُ مُذْعِناً باشد.\n۴. أَخْلَصَ لَهُ مُوَحِّداً باشد.\n۵. عَظَّمَهُ مُمَجِّداً باشد.\n۶. لَاذَ بِهِ رَاغِباً مُجْتَهِداً باشد.\nنکاتی دررابطه‌با ابتدای خطبه و اسامی که ذکر شده:\nنوف البکالی: در حکمت ۱۰۴ نامشان آمده که حضرت در آنجا مطالب عرفانی را به ایشان گوشزد کردند و یکی از اصحاب و از دربان‌های حضرت بوده و شب‌ها به همراه حضرت در مسجد می‌ماندند.\nجعده بن هبیره المخزومی:\nجعده در اینجا نام مرد است، لفظی مرکب است که برای مذکر و مؤنث به کار می‌رود.\nایشان پسر هبیره است.\nهبیره شوهرخواهر امیرالمؤمنین است که از مخالفان پیامبر بود و تلاش‌های زیادی هم در مقابل پیامبر کرد و اوج آن در جنگ احزاب بود؛ ولی وقتی گسترش اسلام را دید از مکه به یمن فرار کرد و از آن زمان دیگر اسمی از او نیست.\nام هانی: خواهر تنی امیرالمؤمنین و مادر جعده است. طبق نقل‌های تاریخی ایشان هیچ‌گاه سابقه کفر نداشته، ولی زمان ظهور ایمانشان به پیامبر، زمان فتح مکه است که مشخص نیست از قبل به‌خاطر شرایط مکه به‌صورت پنهانی ایمان آورده بوده یا نه؟\nپیامبر چندین بار به معراج رفتند؛ یکی از معراج‌های پیامبر در خانه‌ام هانی صورت گرفت که این نشان از طیب‌وطاهر بودن خانه اوست.\nپیامبر و امیرالمؤمنین علاقه خاصی به ام هانی داشته‌اند. روایات زیادی را ایشان از پیامبر نقل کرده‌اند از جمله:\nحدیث غدیر (به سبب حضورشان در حجةالوداع) و حدیث ثقلین هم از دیگر احادیث است.\nامیرالمؤمنین چند نامه برای ایشان نوشته بودند؛ ایشان زنی سیاست‌مدار بوده و مواضع سیاسی داشته‌اند، از جمله بعد از رحلت پیامبر به نفع امیرالمؤمنین موضع گرفتند.\nدر کتاب کفایت الاثر خزاز قمی آمده که پیامبر فرمودند:\n«مَعَاشِرَ الْمُسْلِمِینَ، أَلَا أَدُلُّکُمْ عَلَی خَیْرِ النَّاسِ جَدّاً وَجَدَّةً؟»\nمی‌خواهید به شما بگویم بهترین افراد از جهت اجدادشان چه کسانی هستند؟\nگفتند: بله یا رسول‌الله.\n«قَالَ: الْحَسَنُ وَالْحُسَیْنُ، جَدُّهُمَا رَسُولُ اللَّهِ (ص) خَاتَمُ الْمُرْسَلِینَ، وَجَدَّتُهُمَا خَدِیجَةُ بِنْتُ خُوَیْلِدٍ، سَیِّدَةُ نِسَاءِ أَهْلِ الْجَنَّةِ»\nفرمودند حسن و حسین که من و خدیجه جد و جده آن‌ها هستیم.\n«أَلَا أَدُلُّکُمْ عَلَی خَیْرِ النَّاسِ أَبَا وَأُمّاً؟»\nمی‌خواهید به شما بگویم بهترین شما از جهت پدر و مادر چه کسانی هستند؟\nگفتند: بله یا رسول‌الله.\n«قَالَ: الْحَسَنُ وَالْحُسَیْنُ، أَبُوهُمَا عَلِیُّ بْنُ أَبِی طَالِبٍ، وَأُمُّهُمَا فَاطِمَةُ بِنْتُ مُحَمَّدٍ»\nفرمودند حسن و حسین که پدرشان علی و مادرشان فاطمه دختر من است.\n«ثُمَّ قَالَ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ: أَلَا أَدُلُّکُمْ عَلَی خَیْرِ النَّاسِ عَمّاً وَعَمَّةً؟»\nمی‌خواهید به شما بگویم بهترین شما از جهت عمه و عمو چه کسانی هستند؟\nگفتند: بله یا رسول‌الله.\n«قَالَ: الْحَسَنُ وَالْحُسَیْنُ عَمُّهُمَا جَعْفَرُ بْنُ أَبِی طَالِبٍ، وَعَمَّتُهُمَا أُمُّ هَانِئٍ بِنْتُ أَبِی طَالِبٍ»\nفرمودند حسن و حسین که عموی آن‌ها جعفر است و عمه آن‌ها ام هانی است.\nجعده در زمان فتح مکه ملاقاتی با پیامبر داشتند؛ به همین جهت برخی او را به‌عنوان صحابه هم می‌شناسند؛ ولی از جهت شخصیت، یک انسان بسیار سخنور، مبارز، جنگجو، عالم و فقیه هستند. ایشان در کوفه ساکن بود؛ وقتی هم امیرالمؤمنین از جنگ جمل به کوفه برگشته بودند عده‌ای خواستند حضرت در دارالاماره ساکن شوند؛ ولی ایشان به جهت حضور دیگر خلفا درگذشته در آنجا نپذیرفتند و فرمودند: من به خانه جعده می‌روم. انتخاب خانه‌ام هانی توسط پیامبر و خانه جعده توسط امام علی نشان از جایگاه والای ایشان بوده است.\nجعده داماد امیرالمؤمنین است؛ دختری دارند که در نامشان اختلاف است، ام الحسن یا ام الحسین هست که جعده همسر ایشان است. ایشان برای مدت کوتاهی به‌عنوان والی خراسان انتخاب شد؛ ولی به دلایلی ماندگار نشد؛ لذا در صفین پابه‌رکاب حضرت بود و جنگ نمایانی داشت و مهم‌تر اینکه در شب شهادت امیرالمؤمنین که همه به جهت حالات حضرت از نزدیک بودن زمان شهادتشان باخبر بودند، ام‌کلثوم به نزد حضرت آمد و عرضه داشت: شما امشب برای نماز صبح به مسجد نروید و جعده را به نماز جماعت بفرستید (ایشان هرگاه نمی‌توانستند به جهت کاری به مسجد بروند جعده را به امامت مسجد می‌فرستادند).\nاما امام مخالفت کردند و فرمودند که جعده هم همراهشان به مسجد برود.\nدر روایت داریم بعد از اینکه امیرالمؤمنین ضربه خوردند و نتوانستند نماز جماعت بخوانند، جناب جعده جلو ایستاد و نماز را اقامه کرد، ولی مرحوم مجلسی بیان می‌کند که امام حسن جلوی نمازگزاران ایستادند که این اختلاف روایت وجود دارد؛ ولی چندان مهم نیست، چون درهرصورت نشان از مقام والای جناب جعده در نزد امیرالمؤمنین است.\nدر روایت است که وقتی در جنگ صفین کار بالا گرفته بود امویان طلب مبارز می‌کردند که در آن زمان امیرالمؤمنین جعده را فرستاد که موجب ترس آن‌ها شد و آن‌ها گفتند که تو به دایی خود علی رفته‌ای.\nکه ایشان پاسخ داد:\n«فَوَاللَّهِ لَوْ کَانَ لَکَ خَالٌ مِثْلُهُ لَنَسِیتَ أَبَاکَ»\nشما هم اگر یک دایی به بزرگی علی داشتید نسب خود را فراموش می‌کردید و به علی شبیه می‌شدید.\nاللَّهُمَّ الْحِقْنَا بِالصَّالِحِینَ.","بخش دوم\nمتن:\nالله الواحد:\nلَمْ يُولَدْ سُبْحَانَهُ فَيَكُونَ فِي الْعِزِّ مُشَارَكاً، وَ لَمْ يَلِدْ فَيَكُونَ مَوْرُوثاً هَالِكاً، وَ لَمْ يَتَقَدَّمْهُ وَقْتٌ وَ لَا زَمَانٌ وَ لَمْ يَتَعَاوَرْهُ زِيَادَةٌ وَ لَا نُقْصَانٌ، بَلْ ظَهَرَ لِلْعُقُولِ بِمَا أَرَانَا مِنْ عَلَامَاتِ التَّدْبِيرِ الْمُتْقَنِ وَ الْقَضَاءِ الْمُبْرَمِ. فَمِنْ شَوَاهِدِ خَلْقِهِ خَلْقُ السَّمَاوَاتِ مُوَطَّدَاتٍ بِلَا عَمَدٍ، قَائِمَاتٍ بِلَا سَنَدٍ، دَعَاهُنَّ فَأَجَبْنَ طَائِعَاتٍ مُذْعِنَاتٍ، غَيْرَ مُتَلَكِّئَاتٍ وَ لَا مُبْطِئَاتٍ، وَ لَوْ لَا إِقْرَارُهُنَّ لَهُ بِالرُّبُوبِيَّةِ وَ إِذْعَانُهُنَّ بِالطَّوَاعِيَةِ، لَمَا جَعَلَهُنَّ مَوْضِعاً لِعَرْشِهِ وَ لَا مَسْكَناً لِمَلَائِكَتِهِ وَ لَا مَصْعَداً لِلْكَلِمِ الطَّيِّبِ وَ الْعَمَلِ الصَّالِحِ مِنْ خَلْقِهِ. جَعَلَ نُجُومَهَا أَعْلَاماً يَسْتَدِلُّ بِهَا الْحَيْرَانُ فِي مُخْتَلِفِ فِجَاجِ الْأَقْطَارِ؛ لَمْ يَمْنَعْ ضَوْءَ نُورِهَا ادْلِهْمَامُ سُجُفِ اللَّيْلِ الْمُظْلِمِ وَ لَا اسْتَطَاعَتْ جَلَابِيبُ سَوَادِ الْحَنَادِسِ أَنْ تَرُدَّ مَا شَاعَ فِي السَّمَاوَاتِ مِنْ تَلَأْلُؤِ نُورِ الْقَمَرِ.\nفَسُبْحَانَ مَنْ لَا يَخْفَى عَلَيْهِ سَوَادُ غَسَقٍ دَاجٍ وَ لَا لَيْلٍ سَاجٍ، فِي بِقَاعِ الْأَرَضِينَ الْمُتَطَأْطِئَاتِ وَ لَا فِي يَفَاعِ السُّفْعِ الْمُتَجَاوِرَاتِ، وَ مَا يَتَجَلْجَلُ بِهِ الرَّعْدُ فِي أُفُقِ السَّمَاءِ وَ مَا تَلَاشَتْ عَنْهُ بُرُوقُ الْغَمَامِ، وَ مَا تَسْقُطُ مِنْ وَرَقَةٍ تُزِيلُهَا عَنْ مَسْقَطِهَا عَوَاصِفُ الْأَنْوَاءِ وَ انْهِطَالُ السَّمَاءِ، وَ يَعْلَمُ مَسْقَطَ الْقَطْرَةِ وَ مَقَرَّهَا وَ مَسْحَبَ الذَّرَّةِ وَ مَجَرَّهَا، وَ مَا يَكْفِي الْبَعُوضَةَ مِنْ قُوتِهَا، وَ مَا تَحْمِلُ [مِنَ] الْأُنْثَى فِي بَطْنِهَا.\nترجمه:\nاو از کسى متولد نشده تا همتايى در عزّت و قدرت داشته باشد و فرزندى به دنيا نياورده تا پس از وفاتش وارث او گردد. وقت و زمانى پيش از او نبوده و زيادى و نقصانى بر او عارض نشده است; بلکه به سبب نشانه هاى تدبير متقن و نظام محکمى که به ما ارائه داده عظمتش پيش چشم عقلها آشکار شده است.\nاز شواهد خلقت (حکيمانه و) با عظمت او آفرينش آسمانهاى پابرجايى است که بدون ستون و تکيه گاهى برپاست. خداوند آنها را به قبول فرمان خويش دعوت کرد و آنها با اطاعت و اذعان در برابر او بدون درنگ و سستى دعوتش را پذيرفتند و اگر اقرار آنها به ربوبيت خداوند و اذعانشان به اطاعت او نبود هرگز آنجا را محلّ عرش خود و مسکن فرشتگان (مقرّب) و محل بالا رفتن سخنان پاک و اعمال صالح بندگانش قرار نمى داد.\nخداوند ستارگان آسمان را نشانه هايى قرارداد تا انسانهاى سرگردان را در شب تاريک در نقاط مختلف رهنمون گردد. نه پرده هاى تاريک شبهاى ظلمانى مانع نورافشانى ستارگان مى شود و نه چادر سياه و تاريک آن مى تواند از تلألؤ نور ماه در پهنه آسمانها جلوگيرى کند.\nمنزه است خداوندى که ظلمت شبهاى تار و خاموش در نقاط پست زمين و در قله هاى کوتاه و بلند کوهها که در کنار يکديگر قرار دارند بر او مخفى نيست. و نه آنچه را که غرّش رعد در کرانه هاى آسمان به وجود مى آورد و آنچه برقهاى ابر آن را پراکنده مى سازد و همچنين آنچه را تندبادها از برگهاى درختان فرو مى ريزد يا دانه هاى باران آنها را از شاخه ها جدا مى سازد و نيز از محل سقوط و قرارگاه قطرات باران و جايگاه کشش دانه ها به وسيله مورچگان و حرکات آنها (بر روى زمين) و غذايى که پشه را کفايت مى کند و آنچه انسان يا حيوانات ماده در رحم دارند، از همه اينها آگاه است.\nتفسیر:\nابتدای خطبه دربارهٔ توحید و نکات مهمی در سه بخشِ حمد، استعانت و ایمان بیان شده است. در ادامهٔ همان بخش نخست، مطالب توحیدی بسیار فصیح و بلیغ‌اند. ابن ابی‌الحدید معتزلی در شرح نهج‌البلاغه می‌نویسد: این بخش از فصیح‌ترین کلمات نهج‌البلاغه است.\nلَمْ یولَدْ سُبْحانَهُ فَیکونَ فِی الْعِزِّ مُشارَکاً\nاز صفات خداوند متعال این است که زاییده نشده تا در عزت، شراکتی داشته باشد. خدای متعال، چون زاییده نشده و والدینی ندارد، در عزت نیز شریکی ندارد؛ هر چه عزت است، از آنِ اوست. انسان‌ها، به‌ویژه حاکمان و سلاطین، این ویژگی را دارند که اگر کسی به مقام سلطنت برسد، مخصوصاً در سلطنت‌های موروثی، عزت خود را مرهون پادشاه پیشین است. خدای متعال عزیز است و تمام عزت را دارد و عزتش را مرهون هیچ‌کس نیست.\nوَلَمْ یلِدْ فَیکونَ مَوْرُوثاً هالِکاً\nخدا کسی را نزاییده تا پس از آنکه هلاک شد، همهٔ عزت و جبروتش به فرزندش برسد. خدا زاده نشده تا عزت را از کسی بگیرد و نزاییده است تا عزت را به کسی بدهد؛ عزت مختص خود اوست.\nعزت، گمشدهٔ حقیقی مؤمن است؛ اگر مؤمن باخدا همسو شود و در برابر خدا سر به سجده بگذارد، خدا از عزت خود به او نیز می‌دهد. عزت مختص خدا، پیامبر و مؤمنان است. کسانی که با خداوند انس داشته باشند، به عزت می‌رسند؛ ولی دوری از خدا عزتی ندارد. عزت در برابر عبودیت است.\nروزی مردم بصره به امام حسین نامه نوشتند و از ایشان دربارهٔ لفظ صمد سؤال کردند. صمد یعنی بی‌نیاز؛ کسی که بی‌نیاز باشد، عزیز است. امام حسین در پاسخ فرمودند هیچ‌کس نمی‌تواند قرآن را بر اساس گمان خود تفسیر کند. در پاسخ، حضرت فرمودند صمد را خدا ترجمه کرده است؛ فرمود: بی‌نیاز بودن خدا؛ قُلْ هُوَ اللَّهُ أَحَدٌ، اللَّهُ الصَّمَدُ. خدا عزت محض است؛ چون لَمْ یلِدْ وَلَمْ یولَدْ است؛ نزاییده و زاییده نشده است، عزت را از کسی نگرفته و قرار نیست به کسی بدهد. عزت متعلق به خود اوست. مرگ و تغییروتحول در بارگاه او راهی ندارد؛ پیری و ضعف نیز در بارگاه او راهی ندارد و این معنای صمد و عزیز بودن است.\nوَلَمْ یتَقَدَّمْهُ وَقْتٌ وَلا زَمانٌ\nیکی از صفات خدا این است که وقت و زمان بر او سبقت نگرفته است. چنین نیست که زمانی بوده باشد و خدا نباشد و سپس خدا خلق شده باشد؛ وقت و زمان، مخلوق خدا هستند. کانَ اللَّهُ وَلَمْ یکنْ مَعَهُ شَیءٌ؛ خدا بود و هیچ نبود. زمان را خدا خلق کرد.\nوقت و زمان اگرچه شباهت معنایی دارند، مترادف نیستند. وقت، زمان خاصی است؛ یعنی محدودهٔ زمانی مشخص، مانند زمان دانشگاه رفتن؛ ولی به کل عمر، زمان می‌گویند. نه برهه‌ای خاص و نه کل زمان بر خدا مقدم نشده است؛ خدا اول و آخر است و پیش‌وپس از او چیزی نیست.\nوَلَمْ یتَعاوَرْهُ زِیادَةٌ وَلا نُقْصانٌ\nبر خداوند متعال، زیادی و نقصان پشت‌سرهم وارد نشده است؛ یک روز خسته باشد، یک روز سرحال باشد و یک روز به خواب رود.\nزیادی و نقصان در خدا راه ندارد؛ چون خدا کمال مطلق است و چیزی برای به‌دست‌آوردن ندارد. ما در طول عمر به کلاس و مدرسه می‌رویم تا علم خود را افزایش دهیم؛ زیرا عالم نبوده‌ایم. خدا علم محض و کمال مطلق است؛ خدا نه روبه‌بالا می‌رود و نه سقوط می‌کند. ضعف در خدا راهی ندارد.\nپس در برابر این خدا هیچ‌گونه معرفتی نمی‌توانیم به دست بیاوریم. فرمود: درست است که کنه ذات خدا بر شما آشکار نیست.\nبَلْ ظَهَرَ لِلْعُقُولِ بِما أَرانا مِنْ عَلاماتِ التَّدْبِیرِ الْمُتْقَنِ وَالْقَضاءِ الْمُبْرَمِ\nاما خدا بر عقل‌ها آشکار شده است. حضرت حد و حدود را مشخص کرده‌اند؛ بعضی مراتب توحید را فقط انبیا و اولیا می‌دانند و از فهم بشر دور است. حضرت ابتدا منطقهٔ ممنوعه را ذکر می‌کنند و سپس می‌فرمایند راه خداشناسی بسته نیست. خدا برای عقول، به چیزهایی که از مخلوقاتِ دارای نشانه‌های محکم و متقن نشان داده، آشکار شده است.\nاین عالم، خود نشانه‌ای محکم و مبرم بر وجود خداست.\nعالم آینه‌ای از وجود خدا و دارای سازمان‌دهی محکم و مبرم است. نظامی که حاکم است و تک‌تک مخلوقات و رابطه‌ای که میان آن‌ها وجود دارد، خورشید و ماه و زمین، نشانهٔ وجود خدا هستند. هر یک از سیارات نشانه‌اند. افزون بر آن‌ها، تناسبات و ارتباطاتشان نیز دلیل وجود خداست. هر چیزی به‌تنهایی آیت است و ارتباط آن با اشیای دیگر، دلیل وجود خداست. این‌ها برای عقل آشکار شده‌اند؛ عقل تحلیل می‌کند و از کوه و دشت، خدا را استنباط می‌کند.\nإِنَّ فِی خَلْقِ السَّماواتِ وَالْأَرْضِ وَاخْتِلافِ اللَّیلِ وَالنَّهارِ لَآیاتٍ لِأُولِی الْأَلْبابِ، آل‌عمران، ۱۹۰.\nرفت‌وآمد شب‌وروز، برای هر کدام از این نمادها، نشانه‌های فراوانی است برای کسانی که فکر می‌کنند.\nفَمِنْ شَواهِدِ خَلْقِهِ خَلْقُ السَّماواتِ مُوَطَّداتٍ بِلا عَمَدٍ\nحضرت از کلی به جزئی می‌رسند. یکی از شواهد، خلق آسمان است که بدون ستون، ایستاده و ثابت هستند.\nدر قرآن آمده است که این آسمان‌ها و کرات و سیاره‌ها سرپا ایستاده‌اند: بِلا عَمَدٍ تَرَوْنَها. در تفسیر آیه دو نظر وجود دارد؛ عده‌ای گفته‌اند «بِلا عَمَدٍ» یعنی ستون ندارند و عده‌ای گفته‌اند ستون دارند، اما شما آن را نمی‌بینید. جملهٔ حضرت مؤید این است که ستون دارند. فرمود: شاهد خلق، همین آسمان‌ها هستند که بدون ستون‌اند.\nقائِماتٍ بِلا سَنَدٍ\nسرپا ایستاده‌اند و تکیه‌گاهی ندارند؛ این دلیل مهمی بر وجود خداست.\nدَعاهُنَّ فَأَجَبْنَ طائِعاتٍ مُذْعِناتٍ غَیرَ مُتَلَکئاتٍ وَلا مُبْطِئاتٍ\nخداوند آن‌ها را فراخواند و آن‌ها با تمام وجود اطاعت کردند؛ مطیع بودند و به وجود خدا اذعان کردند که ما مخلوق تو هستیم.\nهم مطیع بودند و هم به مطیع بودن خود اذعان کردند. آن‌ها بدون توقف و بدون هیچ کندی، از دستور خدا سرپیچی و توقف نمی‌کنند و کند هم نیستند؛ هر چه خدا بگوید، اجابت می‌کنند.\nاینجا نشان‌دهندهٔ فهم و درک جمادات است. در جهان‌بینی توحیدی، تمام موجودات صاحب فهم، شعور و درک هستند و در برابر خدا تواضع دارند. قول دیگر این است که گفته شده همهٔ آن‌ها گوش‌به‌فرمان و آماده‌اند. تعبیر این است که خودشان متوجه‌اند؛ هم خدا آن‌ها را خلق کرده و هم دارای فهم و شعور متناسب با خودشان هستند. مثلاً در حکمت‌ها آمده است: الْحَجَرُ الْغَصِیبُ فِی الدّارِ رَهْنٌ عَلی خَرابِها؛ یک آجر غصبی اگر در بنایی باشد، این آجرکاری می‌کند تا بنایش فروبریزد. آجر دارای فهم و شعور است؛ این آجر بنای بلندی را تخریب می‌کند، شاید چهار یا پنج نسل بگذرد، ولی فرومی‌ریزد.\nروایتی از امام صادق در من لایحضره الفقیه آمده است: خداوند سرزمین‌های انتقام گیرنده دارد. وقتی خدا زمینی را به کسی می‌دهد و شخص وجوهات آن را ندهد، خدا جایی را بر او مسلط می‌کند که مال را از او پس می‌گیرد؛ این زمین، زمین منتقم بوده است.\nاینکه فرمودند هر جایی از زمین که در آن عبادت شده باشد، زمین شهادت می‌دهد، در صورتی پذیرفتنی است که این زمین دیده باشد. اگر در صحنهٔ جرم یا مانند آن حاضر نباشد، شهادت معنا ندارد. این زمین امروز باید بفهمد تا فردا شهادت بدهد.\nدر عالم، چیزی بدون درک و شعور وجود ندارد. همهٔ مخلوقات در حد خود دارای فهم و شعور هستند و فردای قیامت شهادت می‌دهند.\nوَلَوْلا إِقْرارُهُنَّ بِالرُّبُوبِیةِ\nاگر آسمان‌ها اقرار به ربوبیت خدا نمی‌کردند.\nوَإِذْعانُهُنَّ لَهُ بِالطَّواعِیةِ\nو اذعان به طاعت نداشتند.\nلَما جَعَلَهُنَّ مَوْضِعاً لِعَرْشِهِ وَلا مَسْکناً لِمَلائِکتِهِ\nاگر آسمان‌ها پاکی و قداست نداشتند و فرمان خدا را گوش نمی‌دادند، اقرار به ربوبیت و اذعان به طاعت نداشتند، خدا آسمان‌ها را موضع عرش قرار نمی‌داد.\nعرش، محلی است که فرامین خدا از آنجا صادر می‌شود. خدا مکان ندارد، ولی دستوراتش از عرش صادر می‌شود. آسمان برای اینکه عرش الهی باشد، باید مراتبی را گذرانده باشد، به پاکی رسیده و اطاعت او ثابت شده باشد. جایگاه اصلی ملائکه در آسمان است، چون پاک هستند. آسمان‌ها نیز چون مطیع محض خدا هستند، جایگاه ملائکه‌اند.\nوَلا مَصْعَداً لِلْکلِمِ الطَّیبِ وَالْعَمَلِ الصَّالِحِ مِنْ خَلْقِهِ\nاگر آسمان‌ها پاک نبودند، محل صعود کلمات طیبه و اعمال صالح خلق نبودند. هر عمل صالحی که از انسان سر بزند، بالا می‌رود و به آسمان می‌رود و نورانیت دارد؛ چون آسمان طاعت خود را نشان داده است.\nآسمان‌ها به‌خاطر درک و شعوری که داشتند، به حقانیت خدا اعتراف و اطاعت کردند؛ لذا خدا عرش را در آسمان‌ها قرارداد و تمام اعمال صالح را به آسمان می‌فرستد و محل سکونت ملائکه را در آسمان قرار داده است. این، درس عملی برای ماست؛ امیرالمؤمنین وقتی از مطالب عرفانی صحبت می‌کند، بخشی برای علم و آگاهی ماست، ولی بخشی دیگر برای عبرت‌گرفتن است.\nمی‌خواهید وجود شما محل رفت‌وآمد ملائکه و جایگاه عرش الهی شود؟ قَلْبُ الْمُؤْمِنِ عَرْشُ الرَّحْمنِ؛ باید اطاعت و اقرار به ربوبیت داشته باشید.\nروایت است اهل حمد شوید؛ اگر اهل حمد شوید، هر مؤمنی که نماز می‌خواند، سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ می‌گوید؛ یعنی خدایا سخن کسی را که اهل حمد است، گوش کن، تا مورد دعای همهٔ نمازگزاران قرار بگیرید.\nاینجا نیز همین است؛ اگر طیب‌وطاهر باشید و نسبت به اوامر الهی کوتاهی نداشته باشید، تمام خیرات به‌سوی شما می‌آید.\nجَعَلَ نُجُومَها أَعْلاماً یسْتَدَلُّ بِهَا الْحَیرانُ فِی مُخْتَلِفِ فِجاجِ الْأَقْطارِ\nنشانهٔ بعدی این است که خدا ستاره‌ها را نشانه قرارداد تا انسان‌هایی که حیران‌اند و در بیابان راه را گم کرده‌اند، به سبب ستاره‌ها راه را پیدا کنند؛ در رفت‌وآمد در راه‌های زمین و ناحیه‌ها.\nکسانی که در میان‌دره‌های زمین گم شده‌اند نیز به سبب ستاره‌ها راه پیدا می‌کنند. چه کسی ستاره را خلق کرد و آن را دقیق آفرید تا نشانگر راه باشد؟ این ستاره، آیت عظمای خداست.\nلَمْ یمْنَعْ ضَوْءَ نُورِها إِدْلِهْمامُ سُجُفِ اللَّیلِ الْمُظْلِمِ\nتاریکی و روشنایی، جلوی نور خدا را نمی‌گیرند. هیچ تاریکی مانع دیدن خدا نمی‌شود؛ دیدن در اینجا، منظور احاطهٔ علمی است. هیچ‌کدام باعث نمی‌شوند علم خدا به شما کم شود.\nنورانیت ستاره‌ها، شدت تاریکی و پردهٔ شب‌های بسیار تاریک، مانع نمی‌شود که خدا شما را نبیند و شما نور ستاره‌ها را نبینید.\nخدا شب را برای آسایش بشر خلق کرد؛ ستاره‌ها را دارای نور آفرید و شب را دارای تاریکی. نه ستاره باعث روشنایی شب تاریک می‌شود و نه شب موجب محو ستاره‌ها می‌شود. هر کدام در جای خود هستند؛ در تاریکی شب، ستاره دیده می‌شود. آیا این نشانه‌های کمی است؟\nانسان نیز از همهٔ تاریکی‌ها می‌گذرد و ستاره را می‌بیند و راه را پیدا می‌کند. آیا این دلیل کمی است؟\nوَلا اسْتَطاعَتْ جَلابِیبُ سَوادِ الْحَنادِسِ أَنْ تَرُدَّ ما شاعَ فِی السَّماواتِ مِنْ تَلَأْلُؤِ نُورِ الْقَمَرِ\nپوشش و روسری تاریکی شب توانایی ندارد. حضرت شب را به روسری تشبیه می‌کند. وقتی روسری تاریکی شب در آسمان پهن می‌شود، این روسری توانایی ندارد نوری را که از ماه در آسمان پخش شده است، رد کند و عقب بزند. خدا ماه را نیز نورانی کرده است، ولی نور ماه مانع استراحت نمی‌شود؛ هم به سبب نور ماه در جاده‌ها مسیر پیدا می‌شود و هم برای کسانی که در خانه استراحت می‌کنند، مانعی ایجاد نمی‌شود.\nخدانور و تاریکی را که ضد هم هستند، با هم جمع کرده است. آیا این دلیل کمی بر وجود خداست؟ این اجتماع نقیضین را خدا با معیاری دقیق قرار داده است، به‌شرط به‌کارگیری عقل.\nفَسُبْحانَ مَنْ لا یخْفی عَلَیهِ سَوادُ غَسَقٍ داجٍ وَلا لَیلٍ ساجٍ\nپاک و منزه است خدایی که تاریکی شدید شب‌ها و شب‌های آرام، بر او پنهان نیستند.\nهر جا «سُبْحانَ» به کار رود، ضعف ما در برابر کمال مطلق، یعنی خدا، منظور است.\nفِی بِقاعِ الْأَرَضِینَ الْمُتَطاطِئاتِ\nدر گودی‌ها و گوشه‌وکنار زمین، چیزی از خدا پنهان نیست. در گودی‌هایی که شدت تاریکی بیشتر است نیز چیزی بر خدا پوشیده نیست.\nوَلا فِی یفاعِ السُّفْعِ الْمُتَجاوِراتِ\nدر مرتفع‌ترین نقطهٔ کوه‌ها که مجاور هم هستند نیز چیزی از خدا پنهان نیست. در قلهٔ کوه‌ها اگر چیزی اتفاق بیفتد، خدا می‌داند.\nدر دره‌های عمیق، هرچه اتفاق بیفتد، دره که اوج تاریکی است و قله که نقطه‌ای روشن‌تر است، همه را می‌داند.\nوَما یتَجَلْجَلُ بِهِ الرَّعْدُ فِی أُفُقِ السَّماءِ\nسروصدای رعدوبرق در پهنای آسمان بر خدا پوشیده نیست.\nوَما تَلاشَتْ عَنْهُ بُرُوقُ الْغَمامِ\nروشنی‌ای که در لابه‌لای ابرها متلاشی می‌شود، بر خدا پوشیده نیست.\nرعد و تشعشعات بر خدا پنهان نیستند؛ همه چیز در محضر خداست. علم الهی اثر تربیتی دارد؛ اینکه خدا می‌داند، یعنی ما در محضر خدا هستیم؛ پس گناه نکنید.\nوَما تَسْقُطُ مِنْ وَرَقَةٍ تُزِیلُها عَنْ مَسْقَطِها عَواصِفُ الْأَنْواءِ وَانْهِطالُ السَّماءِ\nعلم الهی آن‌قدر وسعت دارد که می‌داند برگی از درخت افتاده است، از کدام شاخه افتاده، محل سقوطش کجاست و این برگ به سبب تندباد افتاده یا به سبب باران درشت. اینکه برگ افتاده، از کدام شاخه افتاده، به چه سبب افتاده و به کجا افتاده است، همه را می‌داند.\nوَیعْلَمُ مَسْقَطَ الْقَطْرَةِ وَمَقَرَّها\nخدا می‌داند یک قطره باران که قرار است ببارد، محل سقوط آن کجاست. خدا محل ریزش قطره و سرانجام این قطره را می‌داند.\nوَمَسْحَبَ الذَّرَّةِ وَمَجَرَّها\nخدا می‌داند آنچه از نظر قوت و غذا برای یک پشه کفایت می‌کند چیست.\nمی‌داند پشه باید چقدر و از کجا تغذیه کند. حضرت روی کوچک‌ترین مصادیق انگشت اشاره نهاده‌اند و از قطرهٔ باران، مورچه، پشه و برگ درخت مثال زده‌اند.\nوَما تَحْمِلُ الْأُنْثی فِی بَطْنِها\nخدا می‌داند بچه‌ای که در شکم موجود ماده است، چیست و سرانجامش چه خواهد بود؛ چه خیر و شری به آن گرفتار می‌شود.\nحضرت به علم الهی اشاره می‌کنند و برای ما درس دارند؛ خدا هم عالم است و هم قادر.\nجایی که حضرت فرموده‌اند عَواصِفُ الْأَنْواءِ، «عَواصِفُ» تندباد است و «الْأَنْواءُ» به طلوع‌کردن یک ستاره می‌گویند. در عرب جاهلی، مردم قائل بودند که ماه در گردش یک‌سالهٔ خود به‌دور خورشید، ۲۸ منزلگاه دارد که در هر منزلی ۱۳ روز می‌ماند و هنگامی که از منزلی به منزل دیگر می‌رود، یک ستاره طلوع و یک ستاره غروب می‌کند و در اثر طلوع و غروب ستاره، باد یا بارانی می‌آید.\nاین بحث آرام‌آرام تبدیل به خرافه شد و از ستاره کمک می‌خواستند تا ستارهٔ «الْأَنْواءُ» طلوع یا غروب کند و باد یا بارانی بوزد.\nستاره را صاحب‌اختیار می‌دانستند. اسلام با این بحث مخالفت کرد. مرحوم مجلسی در بحار، ج ۵۵، ص ۳۱۱، بابی با نام بِالنَّهْی فِی الِاسْتِمْتاعِ أَنْواءِ وَالطِّیرَةِ آورده است؛ نهی شده است که از ستارهٔ انواء طلب باران کنید و فال بد بزنید؛ مبادا از ستاره چیزی طلب کنید.\nحضرت در این بخش، فکر خرافی را نهی می‌کنند و آن را از شرک پالایش می‌دهند.\nامام صادق فرمودند: ثَلاثَةٌ مِنْ عَمَلِ الْجاهِلِیةِ؛ سه کار از آداب جاهلیت هستند:\n۱. الْفَخْرُ بِالْأَنْسابِ؛ فخرفروشی با اجداد.\n۲. الطَّعْنُ فِی الْأَحْسابِ؛ اصالت خانوادگی را زیرسؤال‌بردن؛ با هر طعنه، نیزه‌ای در قلب طرف مقابل فرومی‌برند.\n۳. الِاسْتِسْقاءُ بِالْأَنْواءِ؛ طلب باران از ستارهٔ انواء، از رسوم جاهلیت است.\nاللَّهُمَّ عَجِّلْ لِوَلِیک الْفَرَجَ","بخش سوم\nمتن:\nعَود إلى الحمد:\nوَ الْحَمْدُ لِلَّهِ الْكَائِنِ، قَبْلَ أَنْ يَكُونَ كُرْسِيٌّ أَوْ عَرْشٌ أَوْ سَمَاءٌ أَوْ أَرْضٌ أَوْ جَانٌّ أَوْ إِنْسٌ. لَا يُدْرَكُ بِوَهْمٍ وَ لَا يُقَدَّرُ بِفَهْمٍ وَ لَا يَشْغَلُهُ سَائِلٌ وَ لَا يَنْقُصُهُ نَائِلٌ، وَ لَا يَنْظُرُ بِعَيْنٍ وَ لَا يُحَدُّ بِأَيْنٍ وَ لَا يُوصَفُ بِالْأَزْوَاجِ وَ لَا يَخْلُقُ بِعِلَاجٍ وَ لَا يُدْرَكُ بِالْحَوَاسِّ وَ لَا يُقَاسُ بِالنَّاسِ. الَّذِي كَلَّمَ مُوسى تَكْلِيماً وَ أَرَاهُ مِنْ آيَاتِهِ عَظِيماً بِلَا جَوَارِحَ وَ لَا أَدَوَاتٍ وَ لَا نُطْقٍ وَ لَا لَهَوَاتٍ؛ بَلْ إِنْ كُنْتَ صَادِقاً أَيُّهَا الْمُتَكَلِّفُ لِوَصْفِ رَبِّكَ، فَصِفْ جِبْرِيلَ وَ مِيكَائِيلَ وَ جُنُودَ الْمَلَائِكَةِ الْمُقَرَّبِينَ فِي حُجُرَاتِ الْقُدُسِ، مُرْجَحِنِّينَ مُتَوَلِّهَةً عُقُولُهُمْ أَنْ يَحُدُّوا أَحْسَنَ الْخَالِقِينَ، فَإِنَّمَا يُدْرَكُ بِالصِّفَاتِ ذَوُو الْهَيْئَاتِ وَ الْأَدَوَاتِ وَ مَنْ يَنْقَضِي إِذَا بَلَغَ أَمَدَ حَدِّهِ بِالْفَنَاءِ؛ فَلَا إِلَهَ إِلَّا هُوَ، أَضَاءَ بِنُورِهِ كُلَّ ظَلَامٍ وَ أَظْلَمَ بِظُلْمَتِهِ كُلَّ نُورٍ.\nالوصية بالتقوى:\nأُوصِيكُمْ عِبَادَ اللَّهِ بِتَقْوَى اللَّهِ الَّذِي أَلْبَسَكُمُ الرِّيَاشَ وَ أَسْبَغَ عَلَيْكُمُ الْمَعَاشَ؛ فَلَوْ أَنَّ أَحَداً يَجِدُ إِلَى الْبَقَاءِ سُلَّماً أَوْ لِدَفْعِ الْمَوْتِ سَبِيلًا، لَكَانَ ذَلِكَ سُلَيْمَانَ بْنَ دَاوُدَ (علیه السلام) الَّذِي سُخِّرَ لَهُ مُلْكُ الْجِنِّ وَ الْإِنْسِ مَعَ النُّبُوَّةِ وَ عَظِيمِ الزُّلْفَةِ، فَلَمَّا اسْتَوْفَى طُعْمَتَهُ وَ اسْتَكْمَلَ مُدَّتَهُ، رَمَتْهُ قِسِيُّ الْفَنَاءِ بِنِبَالِ الْمَوْتِ وَ أَصْبَحَتِ الدِّيَارُ مِنْهُ خَالِيَةً وَ الْمَسَاكِنُ مُعَطَّلَةً وَ وَرِثَهَا قَوْمٌ آخَرُونَ. وَ إِنَّ لَكُمْ فِي الْقُرُونِ السَّالِفَةِ لَعِبْرَةً، أَيْنَ الْعَمَالِقَةُ وَ أَبْنَاءُ الْعَمَالِقَةِ؟ أَيْنَ الْفَرَاعِنَةُ وَ أَبْنَاءُ الْفَرَاعِنَةِ؟ أَيْنَ أَصْحَابُ مَدَائِنِ الرَّسِّ الَّذِينَ قَتَلُوا النَّبِيِّينَ وَ أَطْفَئُوا سُنَنَ الْمُرْسَلِينَ وَ أَحْيَوْا سُنَنَ الْجَبَّارِينَ؟ أَيْنَ الَّذِينَ سَارُوا بِالْجُيُوشِ وَ هَزَمُوا [الْأُلُوفَ] بِالْأُلُوفِ وَ عَسْكَرُوا الْعَسَاكِرَ وَ مَدَّنُوا الْمَدَائِنَ.\nترجمه:\nستايش مخصوص خداوندى است که پيش از آن که کرسى يا عرش يا آسمان و زمين يا جن و انسى موجود باشد وجود داشته است. خداوندى که نه با فکر و عقل ژرف انديشان درک مى شود و نه با نيروى فهم اندازه اى براى او مى توان تعيين کرد. هيچ درخواست کننده اى او را به خود (از ديگرى) مشغول نمى سازد و هيچ گاه بخشش و عطايش از خزانه بى کرانش نمى کاهد.\nنه به وسيله چشم مى بيند و نه در مکانى محدود مى شود. نه همتا و همسرى دارد و نه در آفرينش نياز به وسيله اى; نه با حواس درک مى شود و نه با مردم مقايسه مى گردد. او همان کسى است که با موسى سخن گفت و آيات بزرگش را به او نشان داد بى آنکه نياز به اعضا و ابزار و زبان و حنجره داشته باشد. اى کسى که خود را براى بيان اوصاف پروردگارت به زحمت افکنده اى! اگر راست مى گويى جبرئيل و ميکائيل و لشکر فرشتگان مقربين را وصف کن، همانها که دربارگاه قدس به عبادت و خضوع مشغولند و عقولشان از اين که خداوند احسن الخالقين را وصف کند در حيرت فرو مانده است. (آرى!) کسى را مى توان با صفات شناخت که داراى هيأت و اعضا و ابزارى باشد و عمرش در زمان معينى سپرى گردد، معبودى جز او نيست معبودى که با نور خويش هر ظلمتى را روشن ساخته و با تاريکيهايى که آفريده هر نورى را در ظلمت فرو برده است.\nاى بندگان خدا ! شما را به تقوا و پرهيزگارى در برابر خداوند سفارش مى کنم; همان خدايى که لباسهاى فاخر به شما پوشانيد و وسايل زندگى را به فراوانى در اختيارتان قرار داد. (هشيار باشيد دنيا شما را نفريبد چرا که هرگز پايدار نيست).\nاگر کسى راهى به سوى بقا و جاودانگى يا جلوگيرى از مرگ پيدا مى کرد چنين کسى به يقين سليمان بن داود(عليه السلام) بود. همان کس که خداوند حکومت جن و انس را افزون بر نبوّت و قرب پروردگار مسخّر وى ساخت; ولى آن گاه که آخرين روزى اش را برگرفت و مدّت زندگانى اش پايان يافت، کمانهاى فنا تيرهاى مرگ را به سوى او پرتاب کردند و دار و ديار از او خالى گشت، مسکنها (و قصرها)ى او بى صاحب ماند و گروهى ديگر، آن را به ارث بردند.\n(آرى) در قرون گذشته براى شما درسهاى عبرت فراوانى است. کجا هستند «عمالقه» و فرزندان «عمالقه؟!» کجايند فرعونها و فرزندانشان؟ و کجا هستند صاحبان شهرهاى رسّ; همانها که پيامبران را کشتند و چراغ پرفروغ سنّتهاى فرستادگان خدا را خاموش کردند و سنّتهاى جباران را زنده ساختند؟ کجايند آنها که با لشکرهاى گران به راه افتادند و هزاران نفر را شکست دادند و متوارى ساختند; همانها که سپاهيان فراوان گرد آوردند و شهرهاى بسيار بنا نهادند.\nتفسیر:\nحضرت از بحث «سُبْحانَ اللهِ» وارد بحث «الْحَمْدُ لِلَّهِ» می‌شود:\nوَالْحَمْدُ لِلَّهِ الْکائِنِ قَبْلَ أَنْ یَکُونَ کُرْسِیٌّ أَوْ عَرْشٌ، أَوِ السَّماءُ أَوْ أَرْضٌ، أَوْ جانٌّ أَوْ إِنْسٌ.\nحمد مختص خدایی است که پیش از آنکه عرش و کرسی باشند، او بوده است [کائن].\nپیش از آسمان و زمین و پیش از جن و انس، خدا وجود داشت.\nوَلا یُدْرَکُ بِوَهْمٍ، وَلا یُقَدَّرُ بِفَهْمٍ.\nحمد مختص خدایی است که کسی نمی‌تواند با وهم خود بر او احاطه پیدا کند.\nهمچنین نمی‌توان او را بافهم، مقدر و اندازه‌گیری کرد.\nفهم، به معنای درک کلیات است.\nوهم، به معنای درک جزئیات است.\nانسان به‌وسیلهٔ فهم، یک سلسله امور کلی را درک می‌کند و به‌وسیلهٔ وهم، کلیات را بر جزئیات تطبیق می‌دهد. سپس می‌فهمد که سیب شیرین است؛ وقتی شیء خارجی را سیب می‌بیند، نتیجه می‌گیرد که باید شیرین باشد.\nمسئول درک کلیات، فهم است.\nمسئول تشخیص مصداق‌ها، وهم است.\nاین وهم، با وهم و خیالِ اصطلاحی متفاوت است.\nوَلا یَشْغَلُهُ السّائِلُ.\nحمد مختص خدایی است که اگر هزاران نفر دست نیاز بلند کنند، درخواست هر یک از آنان، او را از رسیدگی به دیگری بازنمی‌دارد.\nما به سبب محدودیت‌هایی که داریم، نمی‌توانیم پاسخ‌گوی نیاز همهٔ اشخاص باشیم؛ اما دربارهٔ خدا چنین نیست. خدا به هر یک از نیازهای مخلوقاتش پاسخ می‌دهد؛ همان‌گونه که در خطبهٔ ۱۷۸ آمده است:\n《لا یَشْغَلُهُ شَأْنٌ عَنْ شَأْنٍ، وَلا یُغَیِّرُهُ الزَّمانُ، وَلا یَحْوِیهِ الْمَکانُ》\nخدا آن‌قدر به تو توجه دارد که گویی تو تنها مخلوق او هستی.\nوَلا یَنْقُصُهُ نائِلٌ.\nحمد برای خدایی است که هرچه عطا کند، خزائن او تمام نمی‌شود. هیچ نقصی به رزق او وارد نمی‌شود. خزائن او محدود نیست؛ ارادهٔ الهی رزق را پدید می‌آورد و مقدار محدودی نیست که بخواهد آن را تقسیم کند.\nدر حدیث قدسی، دارایی خداوند چنین تشبیه شده است: اگر تمام مخلوقات از اول تا آخر جمع شوند و همهٔ خواسته‌هایشان را بخواهند و من در یک‌لحظه تمام خواسته‌های آنان را برآورده کنم، این کار چیزی از دارایی من کم نمی‌کند:\n《ما نَقَصَ ذلِکَ مِمّا عِنْدی إِلّا کَما یَنْقُصُ الْمِخْیَطُ إِذا أُدْخِلَ الْبَحْرَ》\nهمان‌گونه که اگر نخ و سوزنی را در دریا فروببریم و بیرون آوریم، آیا چیزی از دریا کم می‌شود؟\nدارایی خدا نیز چنین است؛ اگر روزی به همهٔ مخلوقات هرچه خواسته‌اند عطا کند، چیزی از دارایی او کم نمی‌شود.\nالبته این حدیث، تشبیهی برای درک بهتر دارایی خداست؛ وگرنه حتی به اندازهٔ سرسوزن نیز از دارایی خدا کم نمی‌شود؛ زیرا او نامحدود است.\nوَلا یَنْظُرُ بِعَیْنٍ.\nدر برخی متون «لا یُنْظَرُ» آمده است که آن نیز درست است.\nخداوند با چشم نمی‌بیند: «لا یَنْظُرُ».\nهمچنین با چشم دیده نمی‌شود: «لا یُنْظَرُ»؛ زیرا جسم نیست.\nوَلا یُحَدُّ بِأَیْنٍ.\nخداوند به مکان محدود نیست و مکان او را در برنمی‌گیرد.\nوَلا یُوصَفُ بِالْأَزْواجِ.\nاو به زوجیت، یعنی مثل و مانند، وصف نمی‌شود.\nلَیْسَ کَمِثْلِهِ شَیْءٌ.\nو درعین‌حال:\nیا مَنْ لَهُ الْمَثَلُ الْأَعْلاءُ.\nخدا مِثل ندارد، ولی مَثَل دارد؛ همان‌گونه که علی نمایندهٔ خداست و مَثَل خدا شمرده می‌شود.\nوَلا یَخْلُقُ بِعِلاجٍ.\nخدا در آفرینش عالم، از کسی کمک، چاره یا ابزاری [علاج] طلب نکرد.\nوَلا یُدْرَکُ بِالْحَواسِّ.\nخدا به‌وسیلهٔ حواس، مانند گوش، چشم و لامسه، درک نمی‌شود.\nوَلا یُقاسُ بِالنّاسِ.\nخدا با مردم قابل‌قیاس نیست.\nیکی از مهم‌ترین عواملی که موجب تزلزل توحید در جوامع می‌شود و انسان را به ساختن بت می‌کشاند، همین است که خدا را با مردم مقایسه می‌کنند.\nما نیز علم داریم، اما میان علم ما و علم خدا هیچ شباهتی نیست.\nالَّذی کَلَّمَ مُوسی تَکْلیماً وَأَراهُ مِنْ آیاتِهِ عَظیماً.\nحمد مختص خدایی است که با موسی سخن گفت.\nاگر موسی کلیم است، به سبب همین سخن‌گفتن خدا با اوست.\nخدا آیات عظیم خود را به موسی نشان داد.\nبِلا جَوارِحَ وَلا أَدَواتٍ.\nسخن‌گفتن خدا با ابزار نبود؛ او بدون نطق و زبان سخن گفت.\nوَلا نُطْقٍ وَلا لَهَواتٍ.\nخدا سخن گفت، اما نه با ارتعاش تارهای صوتی و زبان.\nسخن‌گفتن او شکل خاصی داشت و همین، خود نشانه‌ای از آیات عظیم اوست.\nخدا اصواتی خلق می‌کرد که موسی آن‌ها را از شش جهت می‌شنید؛ صدا، موسی را احاطه کرده بود.\nبَلْ إِنْ کُنْتَ صادِقاً أَیُّهَا الْمُتَکَلِّفُ لِوَصْفِ رَبِّکَ.\nای کسی که برای توصیف خدا خود را به‌زحمت می‌اندازی،\nفَصِفْ جِبْریلَ وَمیکائیلَ وَجُنودَ الْمَلائِکَةِ الْمُقَرَّبینَ.\nتو نمی‌توانی خدا را توصیف کنی. اگر در ادعای خود صادق هستی، دو فرشتهٔ مقرب الهی، یعنی جبرئیل و میکائیل، را توصیف کن.\nدر پایان خطبهٔ ۱۱۲ نیز مطلبی شبیه به این آمده است: آیا هنگامی که به خانه‌ای وارد می‌شود، از او آگاه می‌شوی یا وقتی جان کسی را می‌ستاند، او را می‌بینی؟ چگونه جنین را در رحم مادر می‌میرند؟ مَلَک‌الموت از کدام عضو مادر به درون می‌رود؟ آیا روح به فرمان پروردگارش به او پاسخ می‌دهد یا همراه کودک در درون شکم مادر جای گرفته است؟ کسی که از وصف مخلوقی چون خود عاجز است، خدای خود را چگونه وصف تواند کرد؟\n《کَیْفَ یَصِفُ إِلهَهُ مَنْ یَعْجِزُ عَنْ صِفَةِ مَخْلُوقٍ مِثْلِهِ؟》\nاگر صادق هستی که می‌توانی خدا را وصف کنی، پس فرشته‌ای چون جبرئیل یا میکائیل را توصیف کن؛ یا دست‌کم یکی از سربازان عادی آنان را وصف کن.\nکسی نمی‌تواند خدا را وصف کند.\nحتی توان وصف ملائک را نیز ندارد.\nملائک مقربی که پیوسته در خضوع و خشوع‌اند.\nوَجُنودَ الْمَلائِکَةِ الْمُقَرَّبینَ فی حُجُراتِ الْقُدْسِ مُرْجَحِنّینَ.\nدر حال خضوع و خشوع [مُرْجَحِنّینَ].\nحضرت یک مرحله کار را آسان‌تر می‌کند و می‌فرماید: فرشتگان مقرب را نه؛ اگر در ادعای خود صادق هستی، سربازان فرشتگان مقرب را توصیف کن؛ درحالی‌که آنان در حجره‌هایی مقدس، در حال خضوع و خشوع‌اند.\nمُتَوَلِّهَةً عُقولُهُمْ أَنْ یَحُدُّوا أَحْسَنَ الْخالِقینَ.\nدرحالی‌که خود آن ملائکه نیز از محدود و موصوف کردن خدایی که «أَحْسَنَ الْخالِقینَ» است، عاجزند و در شناخت او حیران و سرگردان‌اند.\nوقتی ثابت شد که ما نمی‌توانیم کوچک‌ترین ملائکه را وصف کنیم، حضرت می‌فرماید: به فرض که بتوانید ملائکه را وصف کنید که نمی‌توانید، در توصیف خدا هیچ راهی ندارید؛ زیرا خود ملائکه نیز در فهم و وصف «أَحْسَنَ الْخالِقینَ» درمانده و عاجزند.\nحتی خود ملائکهٔ مقرب نیز نمی‌توانند خالق خود را وصف کنند.\nعقل آنان واله و حیران می‌شود که «أَحْسَنَ الْخالِقینَ» را محدود کنند.\nفَإِنَّما یُدْرَکُ بِالصِّفاتِ ذَوُو الْهَیْئاتِ وَالْأَدَواتِ وَمَنْ یَنْقَضی إِذا بَلَغَ أَمَدَ حَدِّهِ بِالْفَناءِ.\nتنها چیزهایی را می‌توان با توصیف درک کرد که سه ویژگی داشته باشند:\n۱. هیئت و شکل داشته باشند.\n۲. ابزار و اعضا داشته باشند.\n۳. هنگامی که سرآمد عمرشان رسید، فانی شوند و مرگ داشته باشند.\nاما خدا هیچ‌یک از این سه ویژگی را ندارد؛ پس قابل‌توصیف نیز نیست.\nفَلا إِلهَ إِلّا هُوَ.\nپس خدایی جز او نیست؛ همان که همهٔ تاریکی‌ها را با نور خود روشن کرده است.\nبه «لا إِلهَ إِلّا هُوَ» اقرار کنید. حضرت در پایان و برای توصیف خدا می‌فرماید بهترین توصیف این است که بگوییم: هیچ خدایی جز او نیست.\nأَضاءَ بِنورِهِ کُلَّ ظَلامٍ وَأَظْلَمَ بِظُلْمَتِهِ کُلَّ نورٍ.\nهمان خدایی که هر تاریکی را با نور خود روشن کرده و هر نوری را با ظلمت خود تاریک ساخته است.\nبرای این جمله سه معنا ذکر می‌شود:\n۱. خدا کسی است که با نور روز، تاریکی شب را از بین برده و با تاریکی شب، نور روز را از بین می‌برد. شب‌وروز دو آیت از قدرت الهی هستند.\n۲. خدا با نور معرفت الله، تاریکی جهل را از میان برده و با تاریکی جهل و ناآگاهی از خدا، نور معنویت، تقوا و اخلاق را از بین می‌برد. نور در معرفت الله است و ظلمت در نشناختن خدا.\n۳. خدا می‌تواند با نور خود، پیشروی انسان را در تاریک‌ترین لحظات روشن کند؛ دست او را بگیرد و از گرفتاری نجات دهد.\nهمان‌گونه که اگر کسی به خود، علم خود و پول خود متکی شود، خدا می‌تواند راه را چنان بر او تاریک کند که راه را از چاه تشخیص ندهد. باید به خدا توکل کرد، نه به خود.\nأُوصیکُمْ عِبادَ اللهِ بِتَقْوَی اللهِ الَّذی أَلْبَسَکُمُ الرِّیاشَ.\nای بندگان خدا، شما را به تقوای خدایی سفارش می‌کنم که لباس‌های متنوع بر شما پوشاند.\nو لباس را برای شما همچون حصنی استوار قرارداد و شما را از آزار و آسیب‌های محیطی حفظ کرد.\nاین از باب وجوب شکرِ مُنعِم است؛ کاری عقلایی است و تنها به دین اختصاص ندارد.\nشاکر نعمت‌های او باشید و شکر نعمت او، تقواست.\n«ریاش» هم می‌تواند به معنای لباس ظاهری باشد و هم لباس معنوی تقوا؛ لباسی که ما را از گناهان حفظ می‌کند. باتوجه‌به «معاش» در جملهٔ بعد، معنای ظاهری آن ارجح است.\nوَأَسْبَغَ عَلَیْکُمُ الْمَعاشَ.\nتقوای خدایی را رعایت کنید که وسایل راحتی، عیش و امنیت شما را فراهم کرده است.\n《وَجَعَلْنا لَکُمْ فیها مَعایِشَ قَلیلاً ما تَشْکُرونَ\nاعراف - ۱۰》\nپس از آفرینش، برای شما اسباب معیشت فراهم کرد؛ اما چه اندک شکرگزاری می‌کنید.\n«معاش» معنایی گسترده دارد؛ از خوراک و غذا گرفته تا هر چیزی که امکانات رفاهی و موجب عیش و راحتی ما باشد. برای نمونه، آهن؛ اگر آهن نبود، استحکامی وجود نداشت و امنیت و آرامشی در کار نبود. از باب وجوب شکرِ مُنعِم، تقوای الهی را رعایت کنید.\nموضوع بعدی، مرگ است.\nحلقهٔ اتصال دو نعمت یادشده و شکر نعمت با مرگ این است که در میان نعمت‌های فراوان، مراقب باشید فریب دنیا را نخورید و احساس ماندگاری و بقا در دنیا به شما دست ندهد. حب دنیا سبب گناهان بسیار می‌شود.\nامید زندگی ابدی و جاودانه در دنیا نداشته باشید. این امید واهی، راه گناه را باز می‌کند.\nفَلَوْ أَنَّ أَحَداً یَجِدُ إِلَی الْبَقاءِ سُلَّماً أَوْ إِلی دَفْعِ الْمَوْتِ سَبیلاً لَکانَ ذلِکَ سُلَیْمانَ بْنَ داوودَ عَلَیْهِ السَّلامُ.\nاگر کسی راهی به‌سوی جاودانگی می‌یافت یا راه فرار از مرگ را پیدا می‌کرد، سزاوارتر از همه سلیمان نبی بود. فرمانروایی تمام دنیا در اختیار او بود، اما او نیز از دنیا رفت. پیامبران بزرگ رفتند و شما نیز خواهید رفت.\nالَّذی سُخِّرَ لَهُ مُلْکُ الْجِنِّ وَالْإِنْسِ.\nحضرت سلیمان چهار ویژگی داشت که باوجود آن‌ها، دنیا به او وفا نکرد.\nفرمانروایی بر تمام جن و انس، پرندگان، وحوش و تسخیر باد، همه در اختیار او بود.\nمَعَ النُّبُوَّةِ وَعَظیمِ الرُّلْفَةِ.\nاو در کنار نبوت، تقربی عظیم [زلفه] به خدا داشت.\nفَلَمّا اسْتَوْفی طُعْمَتَهُ، وَاسْتَکْمَلَ مُدَّتِهِ.\nوقتی رزق معین او به پایان رسید و مدت عمرش کامل شد.\n«استیفا» یعنی چیزی را به طور کامل به‌دست‌آوردن.\nرَمَتْهُ قِسِیُّ الْفَناءِ بِنِبالِ الْمَوْتِ.\nکمان نابودی تیری به نام مرگ دارد و آن تیر به‌سوی سلیمان نبی پرتاب شد.\n《فَلَمّا قَضَیْنا عَلَیْهِ الْمَوْتَ ما دَلَّهُمْ عَلی مَوْتِهِ إِلّا دابَّةُ الْأَرْضِ تَأْکُلُ مِنْسَأَتَهُ\nسَبَأ - ۱۴》\nهنگامی که مرگ او را مقرر کردیم، هیچ‌چیز آنان را از مرگ او آگاه نکرد، مگر جنبنده‌ای زمینی، یعنی موریانه که عصای او را خورد و مرگش آشکار شد.\nوَأَصْبَحَتِ الدِّیارُ مِنْهُ خالِیَةً.\nتمام سرزمین او از سلیمان پیامبر خالی شد.\nوَالْمَساکِنُ مُعَطَّلَةٌ.\nزمین‌وزمان، همهٔ قصرها، خانه‌ها و سرزمین‌ها ماندند و او رفت.\nوَوَرِثَها قَوْمٌ آخَرونَ.\nو گروهی دیگر، حکومت و اموال او را به ارث بردند.\nوجه ارتباط بخش نخست، یعنی نعمت‌ها و شکر نعمت، با مرگ این است که مراقب باشید فراوانی نعمت، شما را به احساس جاودانگی در دنیا نکشاند.\nباید تقوا را در نظر گرفت و توجه داشت که مرگی در پیش است و باید به آن یقین داشت.\nوَإِنَّ لَکُمْ فِی الْقُرونِ السّالِفَةِ لَعِبْرَةً.\nدر اقوام گذشته و تاریخ، برای شما خردمندان عبرت‌هایی وجود دارد؛ از این عبرت‌ها پند بگیرید.\n《إِنَّ فی ذلِکَ لَعِبْرَةً لِأُولِی الْأَلْبابِ\nآل‌عمران - ۱۳》\nدیگران پیش از ما اموال بیشتر و قدرت شدیدتری داشتند، اما نتوانستند از رفتن جلوگیری کنند؛ ما که در برابر آنان چیزی نیستیم.\n《فَیَنْظُروا کَیْفَ کانَ عاقِبَةُ الَّذینَ مِنْ قَبْلِهِمْ\nکانوا أَکْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً وَآثاراً فِی الْأَرْضِ فَما أَغْنی عَنْهُمْ ما کانوا یَکْسِبونَ\nغافر - ۸۲》\nآیا در زمین سیر نمی‌کنند و نمی‌نگرند که عاقبت گذشتگان چگونه بود؟ آنان بسیار نیرومندتر، پرشمارتر و دارای آثار بیشتری در زمین بودند؛ اما آن همه اندوخته، آنان را از عذاب و مرگ نجات نداد.\nأَیْنَ الْعَمالِقَةُ وَأَبْناءُ الْعَمالِقَةِ؟\nعمالقه و فرزندان عمالقه کجایند؟\nعمالقه، یکی از نوادگان نوح پیامبر، عمالق نام داشت. عمالقه قومی درشت‌هیکل و نیرومند بودند؛ حکومتی طولانی و سرزمینی بسیار وسیع تحت سیطرهٔ خود داشتند، اما مشرک و فاسد بودند و سرانجام با عذاب الهی از بین رفتند.\nأَیْنَ الْفَراعِنَةُ وَأَبْناءُ الْفَراعِنَةِ؟\nفراعنه و فرزندان فراعنه کجایند؟\nفراعنه، لفظی عام برای پادشاهان بود و افراد آن تغییر می‌کردند.\nآن پادشاهان مصر کجایند؟\nوجه نام‌گذاری «أَبْناءُ الْمُلوکِ» این است که پادشاهان در برابر نام، شهرت و مقام خود، مسئولیت‌هایی نیز دارند؛ مردم از آنان انتظارهایی دارند و مورد بازخواست قرار می‌گیرند.\nاما فرزندان پادشاهان کسانی هستند که همهٔ امکانات پادشاه را دارند، اما نه مورد سؤال‌وجواب قرار می‌گیرند و نه مسئولیتی دارند.\nازاین‌رو لذت‌های دنیایی آنان از پادشاهان بیشتر است.\nبه همین دلیل فرمود: فرزندان فراعنه کجایند؟\nغرق در لذت و کام‌جویی بودند، اما همه‌چیزتمام شد و رفتند. روزی ما نیز خواهیم رفت.\nأَیْنَ أَصْحابُ مَدائِنِ الرُّسِّ الَّذینَ قَتَلُوا النَّبِیِّینَ؟\nساکنان سرزمین رَسّ کجایند؟\nآنان کسانی بودند که پیامبران خود را کشتند.\nبرخی گفته‌اند آنان در رود ارس کنونی ساکن بوده‌اند.\nدربارهٔ اصحاب رَسّ قول‌های مختلفی گفته شده است، اما آنچه قطعی است این است که آنان درخت صنوبر که درختی خاص بود، را پرستش می‌کردند.\nپس از گرایش و پرستش مردم، پیامبری بر آنان آمد و با این شرک مبارزه کرد. با دعای همان پیامبر، آن درخت خشک شد.\nاین امر موجب ناراحتی قوم شد و آنان پیامبر خود را در گودالی انداختند و او را به شهادت رساندند. سپس گرفتار عذاب الهی شدند و نابود گشتند.\nحضرت پاک‌ترین افراد که یکی از آنان سلیمان است، را مثال می‌زند و در نهایت بدترین افراد را نیز مثال می‌زند تا روشن شود که مرگ برای همهٔ مخلوقات است.\nوَأَطْفَؤُوا سُنَنَ الْمُرْسَلینَ وَأَحْیَوْا سُنَنَ الْجَبّارینَ.\nسنت پیامبران را خاموش کردند و سنت جباران را زنده ساختند.\nهمه رفتند؛ از تمام آثار، نام و یادشان چیزی باقی نماند، جز امکان عبرت‌گرفتن.\nأَیْنَ الَّذینَ سارُوا بِالْجُیوشِ، وَهَزَمُوا الْأُلوفَ؟\nکجایند کسانی که هنگام حرکت، سپاهشان چنان عظمت و سنگینی داشت که پای بر زمین می‌کوبیدند و زمین به لرزه درمی‌آمد، و دشمنانشان را با هزاران سرباز شکست می‌دادند؟\nوَعَسْکَرُوا الْعَساکِرَ، وَمَدَّنُوا الْمَدائِنَ.\nکجایند آنان که سپاه‌های بزرگ داشتند و شهرهای بزرگ می‌ساختند؟\nدرس کلی این بخش از خطبه آن است که مرگ هر انسان در زمان مقرر خود فرامی‌رسد و تأثیری در روزی انسان ندارد؛ همان‌گونه که دربارهٔ امربه‌معروف و نهی‌ازمنکر آمده است که تأثیری در روزی انسان ندارد.\nاللَّهُمَّ أَعْطِنا ما أَغْفَلْناهُ.","بخش چهارم\nمتن:\nوَ مِنْهَا: قَدْ لَبِسَ لِلْحِكْمَةِ جُنَّتَهَا وَ أَخَذَهَا بِجَمِيعِ أَدَبِهَا مِنَ الْإِقْبَالِ عَلَيْهَا وَ الْمَعْرِفَةِ بِهَا وَ التَّفَرُّغِ لَهَا، فَهِيَ عِنْدَ نَفْسِهِ ضَالَّتُهُ الَّتِي يَطْلُبُهَا وَ حَاجَتُهُ الَّتِي يَسْأَلُ عَنْهَا؛ فَهُوَ مُغْتَرِبٌ إِذَا اغْتَرَبَ الْإِسْلَامُ وَ ضَرَبَ بِعَسِيبِ ذَنَبِهِ وَ أَلْصَقَ الْأَرْضَ بِجِرَانِهِ، بَقِيَّةٌ مِنْ بَقَايَا حُجَّتِهِ، خَلِيفَةٌ مِنْ خَلَائِفِ أَنْبِيَائِهِ.\nترجمه:\nبخش ديگرى از خطبه:\n(آن مرد الهى) براى حفظ حکمت و دانش، زرهى بر تن کرده و حکمت را با تمام آدابش در برگرفته، توجه خاص به آن نموده و آن را به خوبى شناخته و يکسره به آن پرداخته است. حکمت و دانش براى او گمشده اى است که همواره در جستجوى آن است و نيازى اوست که پيوسته در طلب آن است. او به هنگامى که اسلام غروب کند و همچون شترى خسته که از راه رفتن بازماند، و بر زمين قرار گرفته و سينه به آن چسبانده است، پنهان خواهد شد. (آرى) او باقيمانده اى از حجّتهاى خداست و خليفه و جانشينى از جانشينان پيامبران اوست.\nتفسیر:\nفضای اصلی خطبه، توحید است و پس از توحید، حضرت ما را به تقوا توصیه می‌کنند. می‌فرمایند تقوای خدایی را پیشه کنید که آسایش را برایتان فراهم کرده است. سپس مسئلهٔ گریزناپذیر بودن مرگ را مطرح می‌فرمایند که اگر قرار بود مرگ به سراغ کسی نیاید، پیامبران از دیگران سزاوارتر بودند. در میان آنان، سلیمان نبی به چهار دلیلی که ذکر شد، این شایستگی را داشت؛ ولی سرانجام همه مردند.\nوَ مِنْهَا: قَدْ لَبِسَ لِلْحِکمَةِ جُنَّتَهَا\nآن شخص برای حفظ حکمت، سپری مخصوص پوشیده است.\nدربارهٔ مصداق این جملات، میان شارحان نهج‌البلاغه اختلاف‌نظر وجود دارد. برخی مصداق آن را عالمان ربانی، برخی عارفانِ طریقِ إلی‌الله و برخی نیز ائمه علیهم‌السلام، به‌ویژه امام عصر (عج)، دانسته‌اند. از شواهد و قرائن، نظریهٔ اخیر درست‌تر به نظر می‌رسد.\nمرحوم علامه امینی در کتاب الغدیر نقل می‌کند که هنگامی که صدیقهٔ طاهره سلام‌الله‌علیها در آن وضعیت میان درودیوار قرار گرفتند، نام حضرت مهدی (عج) را بر زبان آوردند؛ یعنی آیندهٔ جهان اسلام نیکو است. حضرت امیر علیه‌السلام نیز در این خطبه، نیک‌فرجامی جامعه را بیان می‌کنند.\nهرچه انسان به حق نزدیک‌تر باشد، باطل‌ها بیشتر بر سر راه او قرار می‌گیرند؛ اما نکتهٔ مهم آن است که سرانجام کار را ببینیم؛ خوشی‌هایی را که پس از پایان سختی‌ها فرامی‌رسند. پیروزی نهایی از آنِ حق است.\nحکمت، علمی است که با واقعیت مطابقت داشته باشد؛ برای مثال، پزشکی که علم خود را حکیمانه در مسیر سلامت بیمار به مرحلهٔ عمل می‌رساند، فرایند دارو و درمان متناسب با نوع بیماری و وضعیت بیمار را حکیمانه انجام می‌دهد. خدا حکیم است؛ یعنی هر کاری که انجام می‌دهد، حقی است که با واقعیت مطابقت دارد. او آنچه را واقعیت دارد، اجرا می‌کند. اگر علم با عمل همراه باشد، حکمت به دست می‌آید. حکمت یعنی آنچه را می‌دانید، در عالم خارج به کار ببندید و با واقعیت گره بزنید.\nآن چیست که باید همچون سپری پوشید تا حکمت آسیب نبیند؟\nپیامبر صلی‌الله علیه و آله فرمود: هیچ‌کس نیست که چهل روز اخلاص پیشه کند، مگر آنکه رودخانه‌هایی از حکمت در قلب و زبان او جاری شود.\nاگر می‌خواهید حکمت در حصن حصین حفظ شود، باید تقواپیشه کنید. ممکن است کسی بسیار بداند، اما اگر تقوا نداشته باشد، هنگامی که نوبت عمل می‌رسد، آن علم از بین می‌رود. گناه سم است و هنگامی که انسان به تقوا برسد، از آن دوری می‌کند.\nأَخَذَهَا بِجَمِیعِ أَدَبِهَا مِنَ الْإِقْبَالِ عَلَیهَا وَ الْمَعْرِفَةِ بِهَا\nامام عصر (عج) حکمت را با همهٔ جوانب آن دربرگرفته و مشتاق آن است. یکی از آداب حکمت آن است که انسان به آن حکمت شناخت داشته باشد. اولویت اصلی امام این است که به حکمت برسد و این بدان معنا نیست که ایشان حکمت ندارند.\nپیامبر نیز می‌فرمود: «رَبِّ زِدْنِی عِلْمًا». این سخن به معنای نداشتن علم از سوی ایشان نبود، بلکه خداوند به اهل‌بیت علیهم‌السلام حکمت بی‌انتها عطا کرده است و امام می‌خواهد در حکمت پیش برود.\nفَهِی عِنْدَ نَفْسِهِ ضَالَّتُهُ الَّتِی یطْلُبُهَا وَ حَاجَتُهُ الَّتِی یسْأَلُ عَنْهَا\nحکمت از نظر امام‌زمان (عج)، گمشده‌ای [ضالّه] است که پیوسته آن را طلب می‌کند. تنها امام عصر (عج) چنین نیست؛ در خطبهٔ ۸۰، حضرت می‌فرماید نشانهٔ مؤمن آن است که گمشده‌ای دارد. او خود یا خدا را گم نکرده است؛ آنچه گم‌کرده، حکمت است.\nانسان باید دغدغهٔ حکمت داشته باشد؛ یعنی بفهمد و مطابق فهم خود عمل کند. امام، برترین مؤمن است و گمشدهٔ او حکمت است که پیوسته در پی آن است.\nسؤال: امام‌زمان (عج) در قنوت از خدا چه می‌خواهد؟\nپاسخ: درست است که برای شیعیان طلب بخشش می‌کنند، اما حاجت و دغدغهٔ امام (عج) این است که خداوند حکمت عطا کند. حکمت خدا بر دیگر صفات او غالب است و امام نیز می‌خواهد حکمت او بیشتر شود.\n«تَخَلَّقُوا بِأَخْلَاقِ اللهِ» که پیامبر صلی‌الله علیه و آله فرمود، یعنی حکیم و کاردان شوید و آن را در عمل به کار ببرید.\nفَهُوَ مُغْتَرِبٌ إِذَا اغْتَرَبَ الْإِسْلَامُ\nهنگامی که اسلام به غربت [اِغْتَرَبَ] می‌رود، این شخص، یعنی امام‌زمان (عج)، نیز به غیبت می‌رود. وقتی بدعت‌ها زیاد شوند و نور پرفروغ اسلام کم‌نور شود، امام نیز به غربت می‌رود. مردم به جایی می‌رسند که امام خود را می‌کشند؛ پس امام به غیبت می‌رود تا مردم سربه‌راه شوند و آنگاه ظهور می‌کنند. دورهٔ غیبت، مشابه دوران فترت است. ویژگی‌های دوران فترت که پیامبری در آن نبوده است، در نهج‌البلاغه آمده است: دوره‌ای سخت، دین‌داری دشوار، بدعت‌های فراوان و طردشدن عالمان؛ بنابراین غیبت امام موجب بیشترشدن این موارد می‌شود. کم‌نور شدن اسلام، سبب غیبت و غیبت نیز سبب کم‌نور شدن اسلام می‌شود تا هنگامی که اسلام واقعی ظهور کند و حضرت از غیبت بیرون آیند.\nپیامبر خدا صلی‌الله علیه و آله فرمود:\nاسلام با غربت آغاز شد و به غربت پایان می‌یابد؛ خوشا به حال آنان که در دوران غیبت، پای‌کار اسلام هستند. حضرت علی علیه‌السلام در آغاز غربت اسلام پای‌کار ایستادند؛ ازاین‌رو نخستین مؤمن نام گرفتند. کسانی که در دوران غیبت حضرت، دین‌داری آگاهانه دارند، نه دین‌داری از روی عادت یا ترس، دارای ارزش‌اند؛ دین‌داری‌ای که در میان سختی و امتحان باشد و انسان دین‌دار بماند.\nضَرَبَ بِعَسِیبِ ذَنَبِهِ وَ أَلْصَقَ الْأَرْضَ بِجِرَانِهِ\nحضرت، دین را به شتری تشبیه می‌کنند که هنگام خستگی، دم خود را [عَسیب، استخوان و غضروف دم] محکم بر زمین می‌زند. هنگامی که بسیار خسته است، گردن [جِران] خود را نیز بر زمین می‌گذارد. این دم و گردن بر زمین گذاشتن، کنایه از خستگی فراوان است.\nاسلام به موجود زنده‌ای تشبیه شده است که آن‌قدر خنجر خورده که خسته شده است.\nدر دوران غیبت باید دغدغهٔ دین داشته باشیم تا امام (عج) ظهور کند؛ وگرنه دوباره جریان کربلا تکرار می‌شود.\nبَقِیةٌ مِنْ بَقَایا حُجَّتِهِ، خَلِیفَةٌ مِنْ خَلَائِفِ أَنْبِیائِهِ.\nامام، باقی‌ماندهٔ حجت‌های خداست؛ چه حاضر باشد و چه غایب، وجود او نافع است. امام، خلیفه و جانشین همهٔ انبیای الهی است. همهٔ انبیا آمدند تا حکومت عدل مهدوی برقرار شود و هرکس عظمت، دین‌داری و عدالت انبیا را می‌خواهد، همهٔ این‌ها را در وجود امام عصر (عج) می‌یابد. امام می‌خواهد کاری انجام دهد که انبیا توفیق انجام آن را نیافتند. امام باید سختی‌هایی را که انبیا کشیده‌اند، به ثمر برساند.\nدرست است که امام به دلیل حفظ جانشان در غیبت به سر می‌برند، اما رشد امام و تکامل ایشان در همین غیبت است.\nیکی از دلایل مصداق بودن حضرت حجت (عج) در این خطبه آن است که در کتاب تمام نهج‌البلاغه، خطبه به این صورت آمده است که حضرت فرمودند:\nاگر تمام حاکمان مستکبر که من تک‌تک آنان را می‌شناسم و می‌توانم نام ببرم، با نام خلیفهٔ مسلمین بیایند و شما را متفرق کنند، خداوند روزی همهٔ مؤمنان را جمع می‌کند؛ همان روزی که امام‌زمان (عج) می‌آیند و دل‌ها را به‌سوی هدایت می‌برند. مردم به قرآن رجوع می‌کنند، نه آنکه بر اساس سلیقهٔ خود عمل کنند؛ شخصی که «قَدْ لَبِسَ لِلْحِکمَةِ جُنَّتَهَا….»\nو ادامهٔ خطبه بیان می‌شود.\nغَفَرَ اللهُ لِی وَ لَکمْ، الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِینَ","بخش پنجم\nمتن:\nثم قال عليه السلام:\nأَيُّهَا النَّاسُ، إِنِّي قَدْ بَثَثْتُ لَكُمُ الْمَوَاعِظَ الَّتِي وَعَظَ [بِهَا الْأَنْبِيَاءُ] الْأَنْبِيَاءُ بِهَا أُمَمَهُمْ، وَ أَدَّيْتُ إِلَيْكُمْ مَا أَدَّتِ الْأَوْصِيَاءُ إِلَى مَنْ بَعْدَهُمْ، وَ أَدَّبْتُكُمْ بِسَوْطِي فَلَمْ تَسْتَقِيمُوا وَ حَدَوْتُكُمْ بِالزَّوَاجِرِ فَلَمْ تَسْتَوْسِقُوا. لِلَّهِ أَنْتُمْ، أَ تَتَوَقَّعُونَ إِمَاماً غَيْرِي يَطَأُ بِكُمُ الطَّرِيقَ وَ يُرْشِدُكُمُ السَّبِيلَ؟ أَلَا إِنَّهُ قَدْ أَدْبَرَ مِنَ الدُّنْيَا مَا كَانَ مُقْبِلًا وَ أَقْبَلَ مِنْهَا مَا كَانَ مُدْبِراً، وَ أَزْمَعَ التَّرْحَالَ عِبَادُ اللَّهِ الْأَخْيَارُ وَ بَاعُوا قَلِيلًا مِنَ الدُّنْيَا لَا يَبْقَى بِكَثِيرٍ مِنَ الْآخِرَةِ لَا يَفْنَى. مَا ضَرَّ إِخْوَانَنَا الَّذِينَ سُفِكَتْ دِمَاؤُهُمْ وَ هُمْ بِصِفِّينَ أَلَّا يَكُونُوا الْيَوْمَ أَحْيَاءً يُسِيغُونَ الْغُصَصَ وَ يَشْرَبُونَ الرَّنْقَ؟ قَدْ وَ اللَّهِ لَقُوا اللَّهَ، فَوَفَّاهُمْ أُجُورَهُمْ وَ أَحَلَّهُمْ دَارَ الْأَمْنِ بَعْدَ خَوْفِهِمْ.\nأَيْنَ إِخْوَانِيَ الَّذِينَ رَكِبُوا الطَّرِيقَ وَ مَضَوْا عَلَى الْحَقِّ؟ أَيْنَ عَمَّارٌ وَ أَيْنَ ابْنُ التَّيِّهَانِ وَ أَيْنَ ذُو الشَّهَادَتَيْنِ وَ أَيْنَ نُظَرَاؤُهُمْ مِنْ إِخْوَانِهِمُ الَّذِينَ تَعَاقَدُوا عَلَى الْمَنِيَّةِ وَ أُبْرِدَ بِرُءُوسِهِمْ إِلَى الْفَجَرَةِ؟\nقَالَ ثُمَّ ضَرَبَ بِيَدِهِ [إِلَى] عَلَى لِحْيَتِهِ الشَّرِيفَةِ الْكَرِيمَةِ فَأَطَالَ الْبُكَاءَ ثُمَّ قَالَ (علیه السلام):\n[أَوْهِ] أَوِّهِ عَلَى إِخْوَانِيَ الَّذِينَ تَلَوُا الْقُرْآنَ فَأَحْكَمُوهُ، وَ تَدَبَّرُوا الْفَرْضَ فَأَقَامُوهُ، أَحْيَوُا السُّنَّةَ وَ أَمَاتُوا الْبِدْعَةَ، دُعُوا لِلْجِهَادِ فَأَجَابُوا، وَ وَثِقُوا بِالْقَائِدِ فَاتَّبَعُوهُ.\nثُمَّ نَادَى بِأَعْلَى صَوْتِهِ: الْجِهَادَ الْجِهَادَ عِبَادَ اللَّهِ، أَلَا وَ إِنِّي مُعَسْكِرٌ فِي يَومِي هَذَا، فَمَنْ أَرَادَ الرَّوَاحَ إِلَى اللَّهِ فَلْيَخْرُجْ.\nقَالَ نَوْفٌ وَ عَقَدَ لِلْحُسَيْنِ (علیه السلام) فِي عَشَرَةِ آلَافٍ وَ لِقَيْسِ بْنِ سَعْدٍ رَحِمَهُ اللَّهُ فِي عَشَرَةِ آلَافٍ وَ لِأَبِي أَيُّوبَ الْأَنْصَارِيِّ فِي عَشَرَةِ آلَافٍ وَ لِغَيْرِهِمْ عَلَى أَعْدَادٍ أُخَرَ وَ هُوَ يُرِيدُ الرَّجْعَةَ إِلَى صِفِّينَ، فَمَا دَارَتِ الْجُمُعَةُ حَتَّى ضَرَبَهُ الْمَلْعُونُ ابْنُ مُلْجَمٍ لَعَنَهُ اللَّهُ. فَتَرَاجَعَتِ الْعَسَاكِرُ، فَكُنَّا كَأَغْنَامٍ فَقَدَتْ رَاعِيهَا تَخْتَطِفُهَا الذِّئَابُ مِنْ كُلِّ مَكَانٍ.\nترجمه:\nسپس آن حضرت فرمود: اى مردم من مواعظ و اندرزهايى را که پيامبران به امتهايشان دادند، براى شما بازگو کردم و در ميان شما منتشر ساختم. و نيز آنچه را اوصياى پيامبران به امتهاى بعد رساندند، (و در آنجا که ضرورت داشت) شما را با تازيانه ام ادب کردم; ولى شما به هيچ صراطى مستقيم نشديد. بانگ نواهى پروردگار را در ميان شما سر دادم (که از اختلاف و تفرقه بپرهيزيد); اما هرگز اجتماع نکرديد و متحد نشديد. شما را به خدا آيا انتظار داريد پيشوايى جز من شما را به راه بياورد و طريق حق را به شما نشان دهد؟\nآگاه باشيد آنچه از دنيا روى آورده بود، پشت کرده و آنچه پشت کرده بود، روى آورده است (سنّتهاى پيامبر(صلى الله عليه وآله) فراموش شده و سنن جاهلى در حکومت امويان بازگشته است) بندگان نيک خدا به سرعت تصميم به کوچ گرفتند و متاع اندک دنياى فانى را با سرمايه هاى فراوان آخرتِ ماندگار، مبادله نمودند.\nراستى، برادران ما که خونشان در صفين ريخته شد (و شربت شهادت نوشيدند) اگر امروز زنده نيستند که از اين لقمه هاى گلوگير بخورند و از اين آبهاى ناگوار بنوشند، (و اين حوادث دردناک را ببينند) چه ضررى کردند؟ به خدا سوگند! آنها به لقاى پروردگار نايل شدند و خدا پاداششان را به طور کامل عطا فرمود و آنها را در سراى امن و امان بعد از اين زندگى پر از خوف جاى داد.\nکجايند برادران من؟ همانها که در مسير صحيح گام نهادند و در راه حق پيش افتادند، کجاست «عمار»؟ کجاست «ابن تيّهان»؟ و کجاست «ذوالشهادتين». (سه نفر از بزرگان ياران امام که شربت شهادت نوشيدند). و کجايند کسانى همچون آنان از برادرانشان که پيمان بر جانبازى بستند و سرانجام سرهايشان براى فاجران فرستاده شد!\nآن گاه امام(عليه السلام) دست به محاسن شريف خود زد و مدت طولانى گريست و فرمود:\nآه بر برادرانم. همانها که قرآن را تلاوت مى کردند و به کار مى بستند در فرائض الهى تدبّر مى کردند و به پا مى داشتند. سنّتها را زنده کرده، بدعتها را ميراندند. هنگامى که به سوى جهاد دعوت شدند، مشتاقانه پذيرفتند به رهبر خود اطمينان داشتند و از او پيروى کردند سپس با صداى رسا ندا داد ـ اى بندگان خدا ! جهاد، جهاد! آگاه باشيد من امروز لشکر را به سوى اردوگاه حرکت مى دهم، آن کس که مى خواهد به سوى خدا حرکت کند با ما کوچ نمايد.\nنوف بکالى (راوى اين خطبه) مى گويد: امام(عليه السلام) پرچمى به امام حسين(عليه السلام) براى يک لشکر ده هزار نفرى داد و پرچمى به قيس ابن سعد ـ که رحمت خدا بر او باد ـ براى ده هزار و به ابوايوب انصارى براى ده هزار و براى ديگران هر کدام به تعدادهاى ديگر، و اين در حالى بود که مى خواست به صفين بازگردد ولى هنوز روز جمعه نگذشته بود که ابن ملجم ـ که لعنت خدا بر او باد ـ امام(عليه السلام) را ضربت زد و لشکرها بازگشتند و ما همچون گلّه هايى بوديم که شبان خود را از دست مى دهد و گرگان از هر سو به آنها حمله ور مى شوند و آنها را مى ربايند.\nتفسیر:\nحضرت امیرالمؤمنین (ع) خطاب به مردمانی که از صفین بازگشته و رخداد خوارج و ماجرای حکمیت را به چشم دیده‌اند، می‌فرمایند:\nکار معاویه هنوز به پایان نرسیده است؛ جریان اصلی، مسئله شام است و معاویه. خوارج تنها یکی از فرزندان اویند و خود معاویه باید از سر راه برداشته شود.\n«أَیهَا النَّاسُ، إِنِّی قَدْ بَثَثْتُ لَکمُ الْمَوَاعِظَ الَّتِی وَعَظَ بِهَا الْأَنْبِیاءُ أُمَمَهُمْ»\nای مردم! من تمامی موعظه‌های اخلاقی، عرفانی، انذار و تبشیر را که پیامبران با آن امت‌هایشان را پند می‌دادند، برای شما بیان کردم.\n«وَأَدَّیتُ إِلَیکمْ مَا أَدَّتِ الْأَوْصِیاءُ إِلَی مَنْ بَعْدَهُمْ»\nو تمامی نصایحی را که اوصیای انبیا به جانشینان خود ادا کرده بودند، برای شما بازگو نمودم. از واژه «أَدَّیتُ» استنباط می‌شود که حضرت خود را وصی پیامبر اسلام دانسته و وظایف پیامبران را برای خویش واجب می‌بینند. حضرت می‌فرمایند باری را که تمامی انبیا برای هدایت مردم به دوش کشیده بودند، من به‌تنهایی متحمل شدم؛ به‌گونه‌ای که اگر انبیای اولوالعزم و اوصیای آن‌ها نیز برای هدایت شما می‌آمدند، نصایح آنان را نمی‌پذیرفتید.\n«وَأَدَّبْتُکمْ بِسَوْطِی فَلَمْ تَسْتَقِیمُوا»\nمن با تازیانه کلام، شما را ادب کردم، اما به هیچ صراطی مستقیم نشدید. گاه شلاقِ زبان، تأدیب‌کننده‌تر از هرگونه تنبیه جسمانی است.\n«وَحَدَوْتُکمْ بِالزَّوَاجِرِ فَلَمْ تَسْتَوْسِقُوا»\nمن برای هدایت شما با نواهی تندوتیز (زواجر)، همانند ساربانی که برای حرکت سریع شتران آواز می‌خواند، شما را هشدار دادم، اما پیرامون حق اجتماع نکردید. شما را به‌سوی دوری از نواهی و عذاب الهی فراخواندم، اما گرد هم نیامدید. نه سربه‌راه شدید و نه هم‌افزایی کردید؛ نه از جهت اعتقادی با من بودید و نه در یاری‌رسانی. این تفرقه سبب شد معاویه به اهدافش برسد، حکمیت بر ما تحمیل شود و معاویه از شکست صددرصدی رهایی یابد.\n«لِلَّهِ أَنْتُمْ! أَتَتَوَقَّعُونَ إِمَاماً غَیرِی یطَأُ بِکمُ الطَّرِیقَ»\nخداوند پاداشتان را بدهد! آیا انتظار دارید امامی غیر از من بیاید و بار هدایت شما را به دوش بکشد؟\n«وَیرْشِدُکمُ السَّبِیلَ»\nو شما را به راه راست ارشاد کند؟ با تمام جایگاه عبادی، عرفانی و تقرب به رسول‌الله (ص)، علی نتوانست شما را به راه درست بکشاند؛ چه رسد به دیگران. آیا معاویه و امثال او می‌توانند شما را ادب کنند؟ سود او در جهلِ شماست. حتی اگر تلاش کند شما را اصلاح کند، اصلاح‌شدنی نیستید؛ کسی که به دست علی اصلاح نشد، دیگران نیز نمی‌توانند او را اصلاح کنند.\n«أَلا إِنَّهُ قَدْ أَدْبَرَ مِنَ الدُّنْیا مَا کانَ مُقْبِلًا، وَأَقْبَلَ مِنْهَا مَا کانَ مُدْبِراً»\nآگاه باشید، آنچه از خوبی‌ها (اسلام و سنت پیامبر) روی آورده بود، پشت کرد و آنچه از بدی‌های جاهلیت پشت کرده بود، بازگشت. شما جاهلیت را زنده کردید و سنت‌های پیامبر را می‌راندید. اسلام آمد تا کشتار از بین برود، اما شما با انتخاب خویش و روکردن به معاویه، جاهلیت را بازگرداندید.\n«وَأَزْمَعَ التَّرْحَالَ عِبَادُ اللهِ الْأَخْیارُ»\nبندگان برگزیده خدا عزم کوچ از این دنیا کردند. دنیایی که علی را نخواهد، جای‌ماندن نیست. منظور این است که من که بهترین بنده خدا هستم، آماده رفتن‌ام. شما دنیا را چنان به جاهلیت، شرک و کفر آلوده کردید که خوبان خدا عزیمت کردند و علی نیز تاب ماندن ندارد.\n«وَبَاعُوا قَلِیلًا مِنَ الدُّنْیا لا یبْقَی بِکثِیرٍ مِنَ الْآخِرَةِ لا یفْنَی»\nبرگزیدگان، دنیای قلیلِ فانی را با خیرِ کثیرِ آخرت که همیشگی است، معاوضه کردند. همان‌طور که در قرآن آمده، متاع دنیا اندک است. آنان دنیای کوچک و بی‌ارزش را دادند و آخرت بزرگ و ابدی را گرفتند. منِ علی نیز آماده کوچ هستم و دست از این دنیا شسته‌ام، اما شما مردم دنیا را خریدید و آخرت را رها کردید.\n«مَا ضَرَّ إِخْوَانَنَا الَّذِینَ سُفِکتْ دِمَاؤُهُمْ بِصِفِّینَ»\nبرادران ما که در صفین خونشان ریخته شد و به شهادت رسیدند، ضرر نکردند. اگر امروز بودند، جز تلخی، پیمان‌شکنی و کارشکنی چه می‌دیدند؟ آن‌ها زرق‌وبرق پول معاویه را ندیدند و علی را یافتند. برد با آنان بود که این روزهای تنهایی علی را ندیدند؛ روزگاری که حضرت حتی در لشکر خود نیز مورد هجمه واقع می‌شد. آنان چه ضرری کردند؟ جز اینکه دنیا را دادند و آخرت را خریدند.\n«أَنْ لا یکونُوا الْیوْمَ أَحْیاءً یسِیغُونَ الْغُصَصَ وَیشْرَبُونَ الرَّنِقَ»\nآیا باید می‌ماندند تا این روز را ببینند؟ تا لقمه‌های متعفن دنیا گلوگیرشان شود و از این آب کدر، آلوده و وباخیز بنوشند؟ جامعه‌ای که از امام تبعیت نکند، هر لقمه‌اش گلوگیر است. محبت ولایت امام معصوم است که لقمه را گوارا می‌سازد؛ حال که امام در غربت است، آب خوش از گلوی کسی پایین نمی‌رود.\n«قَدْ وَاللهِ لَقُوا اللهَ فَوَفَّاهُمْ أُجُورَهُمْ»\nبه خدا سوگند که آنان به ملاقات خدا رفتند و خداوند تمامی اجرشان را به طور کامل عطا فرمود. وفات یعنی انتقال کامل انسان با تمام ویژگی‌هایش از این دنیا به آخرت.\n«وَأَحَلَّهُمْ دَارَ الْأَمْنِ بَعْدَ خَوْفِهِمْ»\nخداوند آنان را پس از همه دغدغه‌ها در سرای امن قرارداد. «خوف» در اینجا به معنای دغدغه است، زیرا به تعبیر قرآن، مؤمنان «لا خَوْفٌ عَلَیهِمْ وَ لا هُمْ یحْزَنُونَ» هستند و هیچ واهمه‌ای از دشمن ندارند. آنان کسانی بودند که دغدغه امامشان را داشتند.\nاز اینجا به بعد، حضرت به سبب ناامیدی از نصیحتِ مردم، یاران شهیدشان را خطاب قرار می‌دهند که از سوزناک‌ترین جملات نهج‌البلاغه است:\n«أَینَ إِخْوَانِی الَّذِینَ رَکبُوا الطَّرِیقَ وَمَضَوْا عَلَی الْحَقِّ»\nکجایند برادران من که بر جاده حق سوار شدند و راه حق را طی کردند؟ (برخلاف مسافران عادی که منتظر می‌مانند تا مقدمات سفر فراهم شود، آنان به‌محض رسیدن به جاده، مسیر حق را در پیش گرفتند).\n«أَینَ عَمَّارٌ؟ وَأَینَ ابْنُ التَّیهَانِ؟ وَأَینَ ذُو الشَّهَادَتَینِ؟»\nعمار کجاست؟ ابوهیثم بن التیهان کجاست؟ ذوالشهادتین (خُزیمه بن ثابت انصاری) کجاست؟\n«وَأَینَ نُظَرَاؤُهُمْ مِنْ إِخْوَانِهِمُ الَّذِینَ تَعَاقَدُوا عَلَی الْمَنِیةِ»\nکجایند شبیهان آنان که با هم عهد بستند تا مرگ به سراغشان نیاید، دست از حق برندارند؟\n«وَأُبْرِدَ بِرُؤُوسِهِمْ إِلَی الْفَجَرَةِ»\nهمانانی که سرشان برای رؤسای گناهکار شام فرستاده شد. (در مورد شخص چهارمی که سرش برای معاویه فرستاده شد، می‌توان به محمد بن ابی‌بکر اشاره کرد که پس از شهادت، سرش برای معاویه ارسال شد).\n«ثُمَّ ضَرَبَ بِیدِهِ عَلَی لِحْیتِهِ الشَّرِیفَةِ الْکرِیمَةِ فَأَطَالَ الْبُکاءَ ثُمَّ قَالَ:»\nنوف می‌گوید: حضرت پس از یاد یاران، محاسن خود را در دست گرفتند و در فراق آنان طولانی گریستند، سپس فرمودند:\n«أَوَّاهُ عَلَی إِخْوَانِی»\nآه از فراق برادرانم!\nویژگی‌های یاران حضرت از منظر ایشان:\n«الَّذِینَ قَرَءُوا الْقُرْآنَ فَأَحْکمُوهُ»\n۱. آنان کسانی بودند که قرآن را می‌خواندند و آن را در اندیشه و عمل استوار می‌ساختند.\n«وَتَدَبَّرُوا الْفَرْضَ فَأَقَامُوهُ»\n۲. کسانی بودند که در فلسفه واجبات تدبر کرده و آن‌ها را اقامه می‌کردند.\n«أَحْیوُا السُّنَّةَ وَأَمَاتُوا الْبِدْعَةَ»\n۳. سنت‌های نبوی را زنده می‌کردند و بدعت‌ها را می‌راندند. مؤمنان راستین، پیرو سنت پیامبرند و سنت را از اهل‌سنتِ حقیقی یعنی علی (ع) می‌گیرند. ما در مکتب امیرالمؤمنین آموختیم که شهید زیست کنیم تا شهید بمیریم.\n«دُعُوا لِلْجِهَادِ فَأَجَابُوا، وَوَثِقُوا بِالْقَائِدِ فَاتَّبَعُوهُ»\n۴. هرگاه به جهاد دعوت شدند، پذیرفتند و به رهبرشان اعتماد کرده و از او اطاعت کردند. \n «ثُمَّ نَادَی بِأَعْلَی صَوْتِهِ»\nنوف می‌گوید: حضرت با بلندترین صدای خود فرمودند:\n«الْجِهَادَ الْجِهَادَ عِبَادَ اللهِ!»\nای بندگان خدا، جهاد! جهاد! برای یاری دین خدا به پا خیزید.\n«أَلَا وَإِنِّی مُعَسْکرٌ فِی یوْمِی هَذَا، فَمَنْ أَرَادَ الرَّوَاحَ إِلَی اللهِ فَلْیخْرُجْ.»\nآگاه باشید که من امروز در حال آماده‌سازی لشکری برای حرکت به‌سوی معاویه هستم؛ پس هر کس می‌خواهد به‌سوی رضوان الهی کوچ کند، همراه ما خارج شود.\nرسیدن به مقام قرب الهی جز از طریق پیروی از امامِ حق و جهاد در راه او میسر نیست. با عافیت‌طلبی، کناره‌گیری و سرپیچی از فرمان رهبر، کسی به‌سوی خدا رهسپار نمی‌شود، بلکه چنین رویکردی انسان را در دام شیطان می‌افکند. امیرالمؤمنین (ع) باوجود علم غیب به اینکه شهادتشان نزدیک است و این لشکر به سرانجام نمی‌رسد، هرگز از ادای وظیفه فروگذار نکردند. برخلاف ما که اگر نتیجه‌ی کاری را مجهول یا ناموفق بدانیم، از انجامش دست می‌کشیم، ایشان تا آخرین لحظه به اتمام حجت پایبند بودند. وظیفه‌شناسی، درس بزرگ این فراز از خطبه است.\n«قَالَ نَوْفٌ: وَعَقَدَ لِلْحُسَینِ عَلَیهِ السَّلَامُ فِی عَشَرَةِ آلَافٍ، وَلِقَیسِ بْنِ سَعْدٍ رَحِمَهُ اللهُ فِی عَشَرَةِ آلَافٍ، وَلِأَبِی أَیوبَ الْأَنْصَارِی فِی عَشَرَةِ آلَافٍ، وَلِغَیرِهِمْ عَلَی أَعْدَادٍ أُخَرَ.»\nنوف می‌گوید: این لشکر گرد آمد و امام حسین (ع)، قیس بن سعد، ابی‌ایوب انصاری و دیگران، هر کدام فرماندهی ده‌هزار نفر از سپاهیان را بر عهده گرفتند.\n«وَهُوَ یرِیدُ الرَّجْعَةَ إِلَی صِفِّینَ، فَمَا دَارَتِ الْجُمُعَةُ حَتَّی ضَرَبَهُ الْمَلْعُونُ ابْنُ مُلْجَمٍ لَعَنَهُ اللهُ.»\nحضرت قصد داشتند مجدداً به‌سوی شام و رویارویی با معاویه حرکت کنند، اما هنوز هفته‌ای نگذشته بود که آن ملعونِ شقی، ابن ملجم، حضرت را مضروب ساخت.\n«فَتَرَاجَعَتِ الْعَسَاکرُ.»\nخبر جراحت امیرالمؤمنین (ع) که در سپاه پیچید، لشکر از حرکت باز ایستاد و متفرق شد.\nما که در دوران غیبت به سر می‌بریم، عمق فاجعه‌ی فقدان امام را بهتر درک می‌کنیم:\n«فَکنَّا کأَغْنَامٍ فَقَدَتْ رَاعِیهَا تَخْتَطِفُهَا الذِّئَابُ مِنْ کلِّ مَکانٍ.»\nما همچون گله گوسفندی بودیم که چوپان خود را ازدست‌داده و رها شده باشد؛ از هر سو گرگ‌ها به آن یورش می‌بردند و عده‌ای را می‌ربودند.\nجامعه‌ی بدون امام و سرپرست، بسان گله‌ای است که هر روز طعمه‌ی ددان می‌شود. ما یتیمان آل محمد (ص) هستیم و دوران غیبت، دورانی است که حقیقت این جمله را با تمام وجود حس می‌کنیم. سرپرستی که به او پناه ببریم و از او تبعیت کنیم، در دسترس نیست؛ پس از شهادت امام، شیعه غریب‌تر از همیشه شد. داغ امیرالمؤمنین (ع) همان‌قدر که بر دل دوستان سنگین بود، برای دشمنان گوارا آمد. تاریخ نقل می‌کند که عمرو بن عاص خبر شهادت حضرت را این‌گونه به معاویه رساند:\n«إنَّ الْأَسَدَ الْمُفَرَّشَ ذِرَاعَیهِ بِالْعِرَاقِ لَاقَی شُعُوبَهُ»\n«آن شیری که پنجه‌هایش را در عراق گشوده بود، به دوستان شهیدش پیوست.»\nامیرالمؤمنین (ع) همچون شیری در برابر دنیاطلبان و زیاده‌خواهان ایستادگی کرد و با شهادت ایشان، معاویه‌ها جرئتِ قد علم‌کردن یافتند.\nتحلیل شخصیت‌های ذکر شده در خطبه:\n۱. عمار یاسر: نماد ایمانِ محض.\nعایشه در روایتی می‌گوید: «هر کدام از اصحاب پیامبر (ص) را نام ببرند، می‌توانم نقدی بر او وارد کنم، جز عمار؛ چرا که از رسول خدا شنیدم فرمود: او از سرتاپا غرق در ایمان است.» این گواهیِ دشمنِ عمار، نشان از عظمت اوست.\nپیامبر (ص) فرمودند: «هر کس با عمار دشمنی کند، خدا با او دشمنی خواهد کرد.»\nهمچنین در روایتی آمده: «بهشت مشتاق چهار نفر است: علی، عمار، سلمان و در برخی روایات ابوذر غفاری.»\nوقتی خبر شهادت مالک‌اشتر به معاویه رسید، گفت: «علی دو بازوی قدرتمند داشت؛ عمار بن یاسر که در صفین قطع شد و مالک‌اشتر که امروز از دست رفت.»\n۲. ابوهیثم بن التیهان: از یارانِ سلحشور و حق‌طلبِ حضرت که از همان آغازِ خلافت امام علی (ع) با ایشان بیعت کرد و همواره از حریم ولایت دفاع می‌نمود. او روایتگرِ خطبه‌ای است که مرحوم کلینی در جلد هشتم کافی (صفحه ۳۱) آورده و بر جایگاه رفیع اهل‌بیت (ع) تأکید دارد.\n۳. خزیمه بن ثابت انصاری (ذوشهادتین): پیامبر (ص) او را به دلیلِ ایمانِ راسخ و شهادتِ صادقانه‌اش در معامله‌ای با اعرابی، «ذوشهادتین» نامید. او الگویِ پیرویِ بی‌چون‌وچرا از امام است. رجزهای او در صفین، گواه پایبندی‌اش به راه حق بود.\n۴. قیس بن سعد بن عباده: فرزندِ رئیس خزرج، از صحابیِ پیامبر (ص) و حاکمِ مصر که در برابرِ حیله‌های معاویه استوار ماند. معاویه برای تخریبِ چهره‌ی او شایعه‌سازی کرد و علی‌رغم میلِ امام علی (ع)، فشارهای اطرافیان باعث شد حضرت او را از حکومت مصر برکنار کند.\n۵. ابوایوب انصاری: میزبانِ پیامبر (ص) در هجرت به مدینه که همواره در مسیرِ ولایت ثابت‌قدم ماند.\nاللَّهُمَّ اجْعَلْنَا مِنْ خَیرِ أَعْوَانِهِ وَأَنْصَارِهِ."]});
